css:
@property --adv-wren-turn { syntax: "<angle>"; inherits: false; initial-value: 0deg; }
.adv-wren {
  /* re-theme with these four */
  --adv-wren-bg: oklch(0.205 0.012 255);
  --adv-wren-panel: oklch(0.235 0.013 255);
  --adv-wren-ink: oklch(0.94 0.008 85);
  --adv-wren-accent: oklch(0.81 0.145 72);
  /* derived */
  --adv-wren-line: color-mix(in oklch, var(--adv-wren-ink) 9%, transparent);
  --adv-wren-line2: color-mix(in oklch, var(--adv-wren-ink) 16%, transparent);
  --adv-wren-hover: color-mix(in oklch, var(--adv-wren-ink) 6%, transparent);
  --adv-wren-sunk: color-mix(in oklch, var(--adv-wren-bg) 80%, black);
  --adv-wren-mute: color-mix(in oklch, var(--adv-wren-ink) 66%, var(--adv-wren-bg));
  --adv-wren-faint: color-mix(in oklch, var(--adv-wren-ink) 40%, var(--adv-wren-bg));
  --adv-wren-tint: color-mix(in oklch, var(--adv-wren-accent) 15%, transparent);
  --adv-wren-on: oklch(0.24 0.05 70);
  --adv-wren-get: oklch(0.79 0.14 152);
  --adv-wren-post: oklch(0.79 0.14 70);
  --adv-wren-put: oklch(0.76 0.11 245);
  --adv-wren-patch: oklch(0.77 0.12 305);
  --adv-wren-delete: oklch(0.72 0.16 25);
  --adv-wren-ok: oklch(0.79 0.14 152);
  --adv-wren-warn: oklch(0.82 0.14 80);
  --adv-wren-err: oklch(0.7 0.17 25);
  --adv-wren-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  --adv-wren-ease: cubic-bezier(.2, .8, .2, 1);
  --adv-wren-spring: linear(0, 0.12 5%, 0.42 11%, 0.77 18%, 0.97 25%, 1.05 31%, 1.06 37%, 1.03 45%, 1.005 56%, 0.998 70%, 1);

  position: relative; width: 100%; height: var(--adv-wren-h, 680px); box-sizing: border-box; overflow: clip; isolation: isolate;
  container-type: inline-size; container-name: adv-wren;
  display: grid; grid-template-rows: auto auto minmax(0, 1fr) auto; grid-template-areas: "top" "mnav" "body" "foot";
  border-radius: 14px; background: var(--adv-wren-bg); color: var(--adv-wren-ink); color-scheme: dark; accent-color: var(--adv-wren-accent);
  font: 13px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif; -webkit-font-smoothing: antialiased;

  & *, & *::before, & *::after { box-sizing: border-box; }
  & :focus-visible { outline: 2px solid var(--adv-wren-accent); outline-offset: 1px; }
  & button, & input, & textarea, & select { font: inherit; color: inherit; }
  & button { cursor: pointer; background: none; border: 0; padding: 0; }
  & button:disabled { cursor: not-allowed; opacity: .4; }
  & h3, & p, & ol, & ul, & dl, & dd, & pre { margin: 0; padding: 0; }
  & ol, & ul { list-style: none; }
  & [hidden] { display: none !important; }
  & svg { width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; flex: none; }
  & kbd { display: inline-grid; place-items: center; min-width: 17px; height: 17px; padding: 0 4px; border-radius: 4px; font: 600 10px/1 var(--adv-wren-mono); color: var(--adv-wren-mute); box-shadow: inset 0 0 0 1px var(--adv-wren-line2); }
  & output { font-variant-numeric: tabular-nums; }
}

/* ── top bar ── */
.adv-wren .adv-wren-top { grid-area: top; display: flex; align-items: center; gap: 12px; padding: 10px 14px 10px 16px; border-bottom: 1px solid var(--adv-wren-line); }
.adv-wren .adv-wren-brand {
  display: flex; align-items: center; gap: 10px; margin-right: auto; min-width: 0;
  & svg { width: 24px; height: 24px; color: var(--adv-wren-accent); }
  & span { display: grid; line-height: 1.15; min-width: 0; }
  & b { font-size: 15px; font-weight: 760; letter-spacing: -.02em; }
  & small { font-size: 11px; color: var(--adv-wren-faint); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
}
.adv-wren .adv-wren-env {
  display: flex; padding: 3px; gap: 2px; border-radius: 9px; background: var(--adv-wren-sunk); box-shadow: inset 0 0 0 1px var(--adv-wren-line);
  & button { display: inline-flex; align-items: center; gap: 7px; height: 26px; padding: 0 11px; border-radius: 6px; font-size: 12px; font-weight: 600; color: var(--adv-wren-mute); transition: background .25s, color .25s; }
  & i { width: 7px; height: 7px; border-radius: 50%; background: var(--adv-wren-faint); transition: background .25s, box-shadow .25s; }
  & button[aria-checked="true"] { background: var(--adv-wren-panel); color: var(--adv-wren-ink); box-shadow: 0 1px 2px oklch(0 0 0 / .4); }
  & button[data-env="local"][aria-checked="true"] i { background: var(--adv-wren-ok); box-shadow: 0 0 0 3px color-mix(in oklch, var(--adv-wren-ok) 25%, transparent); }
  & button[data-env="staging"][aria-checked="true"] i { background: var(--adv-wren-warn); box-shadow: 0 0 0 3px color-mix(in oklch, var(--adv-wren-warn) 25%, transparent); }
  & button:hover:not([aria-checked="true"]) { color: var(--adv-wren-ink); }
}
.adv-wren .adv-wren-ghost {
  display: inline-flex; align-items: center; gap: 6px; height: 28px; padding: 0 10px; border-radius: 7px; font-size: 12px; font-weight: 600; color: var(--adv-wren-mute);
  transition: background .2s, color .2s;
  &:hover:not(:disabled), &[aria-expanded="true"] { background: var(--adv-wren-hover); color: var(--adv-wren-ink); }
  & svg { width: 15px; height: 15px; }
}
.adv-wren .adv-wren-mnav { grid-area: mnav; display: none; }

/* ── layout ── */
.adv-wren .adv-wren-body { grid-area: body; min-height: 0; display: grid; grid-template-columns: 236px minmax(0, 1fr); grid-template-areas: "side main"; }
.adv-wren .adv-wren-side { grid-area: side; min-height: 0; display: flex; flex-direction: column; gap: 10px; padding: 12px 10px; background: var(--adv-wren-panel); border-right: 1px solid var(--adv-wren-line); overflow: hidden; }
.adv-wren .adv-wren-main { grid-area: main; min-width: 0; min-height: 0; display: grid; grid-template-rows: auto minmax(0, 1fr); }

.adv-wren .adv-wren-seg {
  display: grid; grid-template-columns: 1fr 1fr; padding: 3px; border-radius: 9px; background: var(--adv-wren-sunk);
  & button { height: 26px; border-radius: 6px; font-size: 12px; font-weight: 600; color: var(--adv-wren-mute); transition: background .2s, color .2s; }
  & button[aria-selected="true"] { background: var(--adv-wren-bg); color: var(--adv-wren-ink); }
  & output { margin-left: 3px; color: var(--adv-wren-faint); font-size: 11px; }
}

/* collection tree */
.adv-wren .adv-wren-tree { flex: 1; min-height: 0; overflow-y: auto; scrollbar-width: thin; scrollbar-color: var(--adv-wren-line2) transparent; display: grid; align-content: start; gap: 1px; }
.adv-wren .adv-wren-col { padding: 4px 8px 8px; font-size: 10.5px; font-weight: 700; letter-spacing: .09em; text-transform: uppercase; color: var(--adv-wren-faint); }
.adv-wren .adv-wren-node {
  display: grid; grid-template-columns: 16px 46px minmax(0, 1fr); align-items: center; gap: 4px; width: 100%; min-height: 29px; padding: 0 8px 0 4px; border-radius: 7px; text-align: left; font-size: 12.5px; color: var(--adv-wren-mute);
  transition: background .18s, color .18s;
  &:hover { background: var(--adv-wren-hover); color: var(--adv-wren-ink); }
  &[aria-selected="true"] { background: var(--adv-wren-tint); color: var(--adv-wren-ink); box-shadow: inset 2px 0 0 var(--adv-wren-accent); }
  & .nm { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
  &.is-folder { grid-template-columns: 16px 18px minmax(0, 1fr) auto; font-weight: 650; color: var(--adv-wren-ink); }
  &.is-folder svg.chev { width: 13px; height: 13px; color: var(--adv-wren-faint); transition: rotate .3s var(--adv-wren-ease); }
  &.is-folder[aria-expanded="false"] svg.chev { rotate: -90deg; }
  &.is-folder svg.fold { width: 15px; height: 15px; color: var(--adv-wren-faint); }
  &.is-folder output { font-size: 11px; color: var(--adv-wren-faint); font-weight: 500; }
  &.is-req { padding-left: 22px; grid-template-columns: 42px minmax(0, 1fr); }
}
.adv-wren .adv-wren-tag { font: 700 10px/1 var(--adv-wren-mono); letter-spacing: .02em; color: var(--adv-wren-get); }
.adv-wren [data-m="POST"] .adv-wren-tag, .adv-wren .adv-wren-tag[data-m="POST"] { color: var(--adv-wren-post); }
.adv-wren .adv-wren-tag[data-m="PUT"] { color: var(--adv-wren-put); }
.adv-wren .adv-wren-tag[data-m="PATCH"] { color: var(--adv-wren-patch); }
.adv-wren .adv-wren-tag[data-m="DELETE"] { color: var(--adv-wren-delete); }

/* history */
.adv-wren .adv-wren-hist { flex: 1; min-height: 0; display: flex; flex-direction: column; gap: 6px; }
.adv-wren .adv-wren-histhead { display: flex; justify-content: space-between; align-items: center; padding: 0 6px; font-size: 10.5px; font-weight: 700; letter-spacing: .09em; text-transform: uppercase; color: var(--adv-wren-faint); }
.adv-wren .adv-wren-link { font-size: 11.5px; font-weight: 600; letter-spacing: 0; text-transform: none; color: var(--adv-wren-accent); &:hover:not(:disabled) { text-decoration: underline; } }
.adv-wren .adv-wren-hist ol { flex: 1; min-height: 0; overflow-y: auto; display: grid; align-content: start; gap: 1px; scrollbar-width: thin; }
.adv-wren .adv-wren-hrow {
  display: grid; grid-template-columns: 44px minmax(0, 1fr) auto; grid-template-rows: auto auto; column-gap: 4px; width: 100%; padding: 6px 8px; border-radius: 7px; text-align: left; transition: background .18s;
  &:hover { background: var(--adv-wren-hover); }
  & .adv-wren-tag { grid-row: span 2; align-self: start; padding-top: 3px; }
  & .p { font: 12px var(--adv-wren-mono); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
  & .s { font: 600 11px var(--adv-wren-mono); }
  & small { grid-column: 2 / -1; font-size: 11px; color: var(--adv-wren-faint); font-variant-numeric: tabular-nums; }
  @starting-style { opacity: 0; translate: -8px 0; }
  transition: background .18s, opacity .35s var(--adv-wren-ease), translate .35s var(--adv-wren-ease);
}
.adv-wren .adv-wren-hempty { padding: 16px 8px; font-size: 12px; color: var(--adv-wren-faint); text-wrap: pretty; }
.adv-wren .s-2 { color: var(--adv-wren-ok); }
.adv-wren .s-4 { color: var(--adv-wren-warn); }
.adv-wren .s-5, .adv-wren .s-0 { color: var(--adv-wren-err); }

.adv-wren .adv-wren-vars {
  display: grid; gap: 3px; padding: 10px; border-radius: 10px; background: var(--adv-wren-sunk); font: 11.5px var(--adv-wren-mono);
  & div { display: grid; grid-template-columns: auto minmax(0, 1fr); gap: 8px; }
  & dt { color: var(--adv-wren-accent); }
  & dd { color: var(--adv-wren-mute); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; text-align: right; }
  & .h { grid-column: 1 / -1; font: 700 10px system-ui; letter-spacing: .09em; text-transform: uppercase; color: var(--adv-wren-faint); margin-bottom: 2px; }
}

/* ── request bar ── */
.adv-wren .adv-wren-bar { display: grid; grid-template-columns: auto minmax(0, 1fr) auto; gap: 8px; padding: 12px 14px; border-bottom: 1px solid var(--adv-wren-line); margin: 0; }
.adv-wren .adv-wren-method { position: relative; }
.adv-wren .adv-wren-mbtn {
  display: inline-flex; align-items: center; justify-content: space-between; gap: 6px; width: 92px; height: 36px; padding: 0 10px 0 12px; border-radius: 9px; background: var(--adv-wren-sunk);
  font: 700 12.5px var(--adv-wren-mono); color: var(--adv-wren-get); box-shadow: inset 0 0 0 1px var(--adv-wren-line2);
  & svg { width: 14px; height: 14px; color: var(--adv-wren-faint); transition: rotate .3s var(--adv-wren-ease); }
  &[aria-expanded="true"] svg { rotate: 180deg; }
  &[data-m="POST"] { color: var(--adv-wren-post); } &[data-m="PUT"] { color: var(--adv-wren-put); }
  &[data-m="PATCH"] { color: var(--adv-wren-patch); } &[data-m="DELETE"] { color: var(--adv-wren-delete); }
}
.adv-wren .adv-wren-menu {
  position: absolute; z-index: 20; top: calc(100% + 6px); left: 0; width: 150px; padding: 5px; border-radius: 10px; background: var(--adv-wren-panel);
  box-shadow: 0 0 0 1px var(--adv-wren-line2), 0 18px 40px -10px oklch(0 0 0 / .6);
  transform-origin: 20% 0; transition: opacity .18s, scale .28s var(--adv-wren-spring), display .28s allow-discrete;
  @starting-style { opacity: 0; scale: .94; }
  & li { display: flex; align-items: center; justify-content: space-between; height: 30px; padding: 0 10px; border-radius: 6px; cursor: pointer; font: 700 12px var(--adv-wren-mono); }
  & li[aria-selected="true"]::after { content: ""; width: 6px; height: 6px; border-radius: 50%; background: currentColor; }
  & li.is-active { background: var(--adv-wren-hover); }
}
.adv-wren .adv-wren-url {
  position: relative; min-width: 0; height: 36px; border-radius: 9px; background: var(--adv-wren-sunk); box-shadow: inset 0 0 0 1px var(--adv-wren-line2); transition: box-shadow .2s;
  &:focus-within { box-shadow: inset 0 0 0 1.5px var(--adv-wren-accent), 0 0 0 4px var(--adv-wren-tint); }
  & input, & .adv-wren-mirror { position: absolute; inset: 0; width: 100%; height: 100%; padding: 0 12px; border: 0; font: 12.5px/36px var(--adv-wren-mono); white-space: pre; letter-spacing: 0; }
  & input { background: transparent; color: transparent; caret-color: var(--adv-wren-ink); outline: none; }
  & input::selection { background: color-mix(in oklch, var(--adv-wren-accent) 35%, transparent); color: transparent; }
  & .adv-wren-mirror { overflow: hidden; pointer-events: none; color: var(--adv-wren-ink); }
  & .v { color: var(--adv-wren-accent); background: var(--adv-wren-tint); border-radius: 4px; }
  & .v.bad { color: var(--adv-wren-err); background: color-mix(in oklch, var(--adv-wren-err) 16%, transparent); }
  & .q { color: var(--adv-wren-faint); }
  & .k { color: oklch(0.82 0.08 230); }
  & .pv { color: oklch(0.83 0.11 145); }
}
.adv-wren .adv-wren-send {
  --adv-wren-turn: 0deg;
  position: relative; display: inline-flex; align-items: center; gap: 9px; height: 36px; min-width: 104px; justify-content: center; padding: 0 14px; border-radius: 9px;
  background: var(--adv-wren-accent); color: var(--adv-wren-on); font-weight: 720; letter-spacing: -.01em;
  transition: filter .2s, scale .25s var(--adv-wren-spring);
  & kbd { color: color-mix(in oklch, var(--adv-wren-on) 70%, transparent); box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--adv-wren-on) 28%, transparent); }
  &:hover { filter: brightness(1.07); }
  &:active { scale: .97; }
  &.is-busy { background: conic-gradient(from var(--adv-wren-turn), var(--adv-wren-accent), color-mix(in oklch, var(--adv-wren-accent) 55%, var(--adv-wren-bg)) 40%, var(--adv-wren-accent)); animation: adv-wren-spin 1s linear infinite; }
}
@keyframes adv-wren-spin { to { --adv-wren-turn: 360deg; } }

/* ── panes ── */
.adv-wren .adv-wren-panes { min-height: 0; display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 1.15fr); grid-template-areas: "req res"; }
.adv-wren .adv-wren-req { grid-area: req; min-height: 0; min-width: 0; display: grid; grid-template-rows: auto minmax(0, 1fr) auto; border-right: 1px solid var(--adv-wren-line); }
.adv-wren .adv-wren-res { grid-area: res; min-height: 0; min-width: 0; display: grid; grid-template-rows: auto auto minmax(0, 1fr); }
.adv-wren .adv-wren-tabs {
  display: flex; align-items: center; gap: 2px; padding: 0 10px; border-bottom: 1px solid var(--adv-wren-line); min-width: 0;
  & [role="tab"] { position: relative; height: 36px; padding: 0 9px; font-size: 12.5px; font-weight: 600; color: var(--adv-wren-mute); white-space: nowrap; transition: color .2s; }
  & [role="tab"]::after { content: ""; position: absolute; left: 8px; right: 8px; bottom: -1px; height: 2px; border-radius: 2px; background: var(--adv-wren-accent); scale: 0 1; transition: scale .35s var(--adv-wren-ease); }
  & [role="tab"][aria-selected="true"] { color: var(--adv-wren-ink); }
  & [role="tab"][aria-selected="true"]::after { scale: 1 1; }
  & [role="tab"]:hover { color: var(--adv-wren-ink); }
  & output { font-size: 11px; color: var(--adv-wren-faint); margin-left: 2px; }
  & output:empty { display: none; }
}
.adv-wren .adv-wren-sp { flex: 1; }
.adv-wren .adv-wren-mini {
  display: flex; padding: 2px; border-radius: 7px; background: var(--adv-wren-sunk);
  & button { height: 22px; padding: 0 8px; border-radius: 5px; font-size: 11.5px; font-weight: 600; color: var(--adv-wren-faint); }
  & button[aria-checked="true"] { background: var(--adv-wren-panel); color: var(--adv-wren-ink); }
}
.adv-wren .adv-wren-copy { height: 26px; }

/* key-value editor */
.adv-wren .adv-wren-rpanel { min-height: 0; overflow-y: auto; scrollbar-width: thin; scrollbar-color: var(--adv-wren-line2) transparent; padding: 10px 12px 14px; }
.adv-wren .adv-wren-kv { display: grid; grid-template-columns: 22px minmax(0, .8fr) minmax(0, 1.2fr) 26px; align-items: center; gap: 0; border-radius: 9px; box-shadow: 0 0 0 1px var(--adv-wren-line); overflow: hidden; }
.adv-wren .adv-wren-kvrow {
  display: grid; grid-column: 1 / -1; grid-template-columns: subgrid; align-items: center; min-height: 34px; border-bottom: 1px solid var(--adv-wren-line); transition: opacity .2s, background .2s;
  &:last-child { border-bottom: 0; }
  &:hover { background: color-mix(in oklch, var(--adv-wren-ink) 2.5%, transparent); }
  &:has(input[type="checkbox"]:not(:checked)) .f { opacity: .42; text-decoration: line-through; text-decoration-color: var(--adv-wren-faint); }
  & input[type="checkbox"] { justify-self: center; width: 13px; height: 13px; margin: 0; cursor: pointer; }
  & .f { width: 100%; height: 34px; min-width: 0; padding: 0 9px; border: 0; border-left: 1px solid var(--adv-wren-line); background: transparent; font: 12px var(--adv-wren-mono); outline: none; transition: background .2s; }
  & .f:focus { background: var(--adv-wren-hover); }
  & .f::placeholder { color: var(--adv-wren-faint); }
  & .del { display: grid; place-items: center; width: 26px; height: 34px; color: var(--adv-wren-faint); border-left: 1px solid var(--adv-wren-line); opacity: .55; transition: opacity .2s, color .2s; }
  & .del svg { width: 13px; height: 13px; }
  &:hover .del, & .del:focus-visible { opacity: 1; }
  & .del:hover { color: var(--adv-wren-err); }
  @starting-style { opacity: 0; }
}
.adv-wren .adv-wren-kvhead { display: grid; grid-column: 1 / -1; grid-template-columns: subgrid; height: 28px; align-items: center; background: var(--adv-wren-sunk); font-size: 10.5px; font-weight: 700; letter-spacing: .08em; text-transform: uppercase; color: var(--adv-wren-faint); & span { padding-left: 10px; } }
.adv-wren .adv-wren-add { display: inline-flex; align-items: center; gap: 6px; margin-top: 8px; height: 28px; padding: 0 9px; border-radius: 7px; font-size: 12px; font-weight: 600; color: var(--adv-wren-mute); &:hover { background: var(--adv-wren-hover); color: var(--adv-wren-ink); } & svg { width: 14px; height: 14px; } }
.adv-wren .adv-wren-hint { margin-top: 10px; font-size: 12px; color: var(--adv-wren-faint); text-wrap: pretty; & code { font: 11.5px var(--adv-wren-mono); color: var(--adv-wren-accent); } }
.adv-wren .adv-wren-bodyed { display: grid; grid-template-rows: auto minmax(160px, 1fr) auto; gap: 8px; height: 100%; }
.adv-wren .adv-wren-bodybar { display: flex; align-items: center; gap: 8px; font-size: 12px; color: var(--adv-wren-mute); & .adv-wren-sp { flex: 1; } }
.adv-wren textarea.adv-wren-json {
  width: 100%; min-height: 160px; resize: none; padding: 10px 12px; border: 0; border-radius: 9px; background: var(--adv-wren-sunk); box-shadow: inset 0 0 0 1px var(--adv-wren-line2);
  font: 12px/1.6 var(--adv-wren-mono); tab-size: 2; outline: none; transition: box-shadow .2s;
  &:focus { box-shadow: inset 0 0 0 1.5px var(--adv-wren-accent); }
  &:disabled { opacity: .45; }
}
.adv-wren .adv-wren-valid { font: 11.5px var(--adv-wren-mono); color: var(--adv-wren-ok); &.bad { color: var(--adv-wren-err); } }
.adv-wren .adv-wren-resolved { padding: 9px 14px; border-top: 1px solid var(--adv-wren-line); font: 11.5px var(--adv-wren-mono); color: var(--adv-wren-faint); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; & b { color: var(--adv-wren-mute); font-weight: 700; } }

/* ── response ── */
