/* ── Wren · API client ───────────────────────────────────────────────
   One working copy per request (drafts), a URL whose query string and the
   Params table stay in two-way sync, and a local fixture router that answers
   like a real API: auth, 400/401/404/405/409/422 problem+json, 201 with
   Location, 204 with no body. Every response carries per-phase timings whose
   sum is the reported time. */
const $ = (s, el = root) => el.querySelector(s);
const $$ = (s, el = root) => [...el.querySelectorAll(s)];
const RM = matchMedia('(prefers-reduced-motion: reduce)');
