/* ── environments and fixtures ── */
const ENVS = {
  local: { name: 'Local', vars: { base: 'http://localhost:4010', token: 'demo-local-7f3a91', carrier: 'nordlane' } },
  staging: { name: 'Staging', vars: { base: 'https://api.staging.tidepool.test', token: 'demo-staging-c42e08', carrier: 'halvard' } },
};
const STATUSES = ['pending', 'in_transit', 'delivered', 'exception'];
const DB = {
  next: 20418,
  shipments: [
    { id: 'SHP-20417', reference: 'PO-88213', status: 'in_transit', origin: 'Rotterdam, NL', destination: 'Lyon, FR', carrier: 'nordlane', weight_kg: 412.5, pieces: 6, eta: '2026-10-04' },
    { id: 'SHP-20416', reference: 'PO-88207', status: 'delivered', origin: 'Hamburg, DE', destination: 'Vienna, AT', carrier: 'halvard', weight_kg: 88, pieces: 1, eta: '2026-10-01' },
