  ],
  carriers: [
    { id: 'nordlane', name: 'Nordlane Haulage', mode: 'road', on_time_rate: 0.962 },
    { id: 'halvard', name: 'Halvard Freight', mode: 'road', on_time_rate: 0.918 },
    { id: 'oxbow', name: 'Oxbow Logistics', mode: 'rail', on_time_rate: 0.947 },
