  { id: 'f-ship', name: 'Shipments', open: true, items: [
    REQ('r-list', 'List shipments', 'GET', '{{base}}/v2/shipments?status=in_transit&limit=3', { extraParams: [{ on: false, k: 'carrier', v: '{{carrier}}' }] }),
