/* ── state ── */
const S = {
  env: 'local', open: 'r-list', side: 'tree', view: 'request', rtab: 'params', xtab: 'body', fmt: 'pretty',
  drafts: {}, req: null, res: null, busy: null, hist: [], folded: new Set(), menu: false, mi: 0, curl: false, rate: 120, seq: 0,
