  const q = S.req.params.filter(p => p.on && p.k).map(p => enc(p.k) + (p.v !== '' ? '=' + enc(p.v) : '')).join('&');
  S.req.url = splitUrl(S.req.url)[0] + (q ? '?' + q : '');
}
function urlToParams() { S.req.params = parseQuery(splitUrl(S.req.url)[1]).concat(S.req.params.filter(p => !p.on)); }

/* ── fixture router ── */
function problem(status, title, detail, path, extra) {
