  const w = (cls, s) => html ? `<span class="${cls}">${esc(s)}</span>` : s;
  const parts = [w('c', 'curl') + (S.req.method !== 'GET' ? ' ' + w('f', '-X') + ' ' + S.req.method : '') + ' ' + w('s', q(resolve(S.req.url)))];
  S.req.headers.filter(h => h.on && h.k).forEach(h => parts.push('  ' + w('f', '-H') + ' ' + w('s', q(h.k + ': ' + resolve(h.v)))));
  if (HAS_BODY(S.req.method) && S.req.body.trim()) {
    let b = resolve(S.req.body); try { b = JSON.stringify(JSON.parse(b)); } catch (e) {}
