/* ── actions ── */
function open(id) {
  S.open = id; S.req = draftOf(id);
  if (S.rtab === 'body' && !HAS_BODY(S.req.method)) S.rtab = 'params';
  if (HAS_BODY(S.req.method) && S.rtab === 'params' && !S.req.params.length) S.rtab = 'body';
