root.addEventListener('click', e => {
  const t = e.target.closest('button, [data-pick]');
  if (!t || !root.contains(t)) return;
  if (S.menu && !t.closest('[data-menu]') && t.dataset.act !== 'method') setMenu(false);
  if (t.dataset.pick) { pickMethod(t.dataset.pick); return; }
  if (t.dataset.folder) { const f = COLL.find(x => x.id === t.dataset.folder); f.open = !f.open; renderTree(); return; }
  if (t.dataset.open) { open(t.dataset.open); return; }
  if (t.dataset.side && t.getAttribute('role') === 'tab') { S.side = t.dataset.side; renderSide(); return; }
