  if (act === 'closecurl') { S.curl = false; renderCurl(); $('[data-act="curl"]').focus(); return; }
  if (act === 'copycurl') { copy(curlText(false), t); toast('cURL command copied'); return; }
  if (act === 'copybody') { if (S.res && S.res.body) { copy(S.fmt === 'raw' ? S.res.body : JSON.stringify(S.res.json, null, 2), t); toast('Response body copied'); } else toast('This response has no body to copy'); return; }
