$('[data-bar]').addEventListener('submit', e => { e.preventDefault(); send(); });

urlIn.addEventListener('input', () => { S.req.url = urlIn.value; urlToParams(); syncMirror(); counts(); if (S.rtab === 'params') renderReq(); if (S.curl) renderCurl(); });
['scroll', 'keyup', 'select', 'click', 'focus'].forEach(ev => urlIn.addEventListener(ev, () => { mirror.scrollLeft = urlIn.scrollLeft; }));
urlIn.addEventListener('keydown', () => requestAnimationFrame(() => { if (!root.isConnected) return; mirror.scrollLeft = urlIn.scrollLeft; }));

const rp = $('[data-rpanel]');
rp.addEventListener('input', e => {
