@property --adv-quarry-n { syntax: "<integer>"; inherits: false; initial-value: 0; }
.adv-quarry {
  /* re-theme with these four */
  --adv-quarry-bg: oklch(0.972 0.005 220);
  --adv-quarry-panel: oklch(0.996 0.002 220);
  --adv-quarry-ink: oklch(0.27 0.03 232);
  --adv-quarry-accent: oklch(0.53 0.1 192);
  /* derived */
  --adv-quarry-line: color-mix(in oklch, var(--adv-quarry-ink) 11%, transparent);
  --adv-quarry-line2: color-mix(in oklch, var(--adv-quarry-ink) 19%, transparent);
  --adv-quarry-hover: color-mix(in oklch, var(--adv-quarry-ink) 5%, transparent);
  --adv-quarry-mute: color-mix(in oklch, var(--adv-quarry-ink) 70%, var(--adv-quarry-bg));
  --adv-quarry-faint: color-mix(in oklch, var(--adv-quarry-ink) 46%, var(--adv-quarry-bg));
  --adv-quarry-tint: color-mix(in oklab, var(--adv-quarry-accent) 11%, var(--adv-quarry-panel));
  --adv-quarry-tint2: color-mix(in oklab, var(--adv-quarry-accent) 20%, var(--adv-quarry-panel));
  --adv-quarry-err: oklch(0.55 0.18 25);
  --adv-quarry-kw: var(--adv-quarry-accent);
  --adv-quarry-str: oklch(0.53 0.12 55);
  --adv-quarry-num: oklch(0.5 0.14 310);
  --adv-quarry-fn: oklch(0.5 0.12 150);
  --adv-quarry-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  --adv-quarry-ease: cubic-bezier(.2, .8, .2, 1);
  --adv-quarry-spring: linear(0, 0.12 5%, 0.42 11%, 0.77 18%, 0.97 25%, 1.05 31%, 1.06 37%, 1.03 45%, 1.005 56%, 0.998 70%, 1);

  position: relative; width: 100%; height: var(--adv-quarry-h, 680px); box-sizing: border-box; overflow: clip; isolation: isolate;
  container-type: inline-size; container-name: adv-quarry;
  border-radius: 14px; background: var(--adv-quarry-bg); color: var(--adv-quarry-ink); color-scheme: light; accent-color: var(--adv-quarry-accent);
  font: 13px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif; box-shadow: inset 0 0 0 1px var(--adv-quarry-line);

  & *, & *::before, & *::after { box-sizing: border-box; }
  & :focus-visible { outline: 2px solid var(--adv-quarry-accent); outline-offset: 1px; }
  & button, & input, & textarea { font: inherit; color: inherit; }
  & button { cursor: pointer; background: none; border: 0; padding: 0; }
  & button:disabled { cursor: not-allowed; opacity: .4; }
  & h3, & p, & ol, & ul, & dl, & dd, & pre { margin: 0; padding: 0; }
  & ol, & ul { list-style: none; }
  & [hidden] { display: none !important; }
  & svg { width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; flex: none; }
  & kbd { display: inline-grid; place-items: center; min-width: 17px; height: 17px; padding: 0 4px; border-radius: 4px; font: 600 10px/1 var(--adv-quarry-mono); color: var(--adv-quarry-mute); background: var(--adv-quarry-panel); box-shadow: inset 0 0 0 1px var(--adv-quarry-line2), 0 1px 0 var(--adv-quarry-line); }
}

.adv-quarry .adv-quarry-app {
