  & button[aria-selected="true"] { background: var(--adv-quarry-panel); color: var(--adv-quarry-ink); box-shadow: 0 1px 2px oklch(0 0 0 / .1), 0 0 0 1px var(--adv-quarry-line); }
}
.adv-quarry .adv-quarry-sidebody { flex: 1; min-height: 0; overflow-y: auto; scrollbar-width: thin; scrollbar-color: var(--adv-quarry-line2) transparent; }
