  & .nm:hover { background: var(--adv-quarry-hover); }
  & .nm[aria-current="true"] { background: var(--adv-quarry-tint); color: color-mix(in oklch, var(--adv-quarry-accent) 70%, var(--adv-quarry-ink)); }
