.adv-quarry .adv-quarry-csv { position: relative; padding: 12px 14px; & pre { padding: 12px; border-radius: 9px; background: color-mix(in oklch, var(--adv-quarry-ink) 3.5%, var(--adv-quarry-panel)); font: 11.5px/1.6 var(--adv-quarry-mono); white-space: pre; overflow: auto; color: var(--adv-quarry-mute); max-height: 100%; } & .adv-quarry-btn { position: absolute; top: 18px; right: 22px; background: var(--adv-quarry-panel); box-shadow: 0 0 0 1px var(--adv-quarry-line2); } }

