.adv-quarry .adv-quarry-insp { grid-area: insp; min-height: 0; overflow-y: auto; scrollbar-width: thin; border-left: 1px solid var(--adv-quarry-line); padding: 14px 14px 18px; display: flex; flex-direction: column; gap: 12px; }
.adv-quarry .adv-quarry-ihead {
