    position: absolute; z-index: 30; top: 49px; right: 0; bottom: 30px; width: min(300px, 86%); background: var(--adv-quarry-bg); box-shadow: -24px 0 48px -24px oklch(0.2 0.03 232 / .45);
    translate: 104% 0; visibility: hidden; transition: translate .45s var(--adv-quarry-spring), visibility 0s .45s;
