  .adv-quarry .adv-quarry-inspbtn, .adv-quarry .adv-quarry-conn { display: none; }
  .adv-quarry .adv-quarry-mnav {
    display: grid; grid-template-columns: repeat(4, 1fr); gap: 4px; padding: 6px 10px; background: var(--adv-quarry-panel); border-bottom: 1px solid var(--adv-quarry-line);
    & button { height: 30px; border-radius: 7px; font-size: 12.5px; font-weight: 600; color: var(--adv-quarry-mute); }
    & button[aria-selected="true"] { background: var(--adv-quarry-tint); color: var(--adv-quarry-ink); }
  }
