  .adv-quarry[data-view="schema"] .adv-quarry-side { display: flex; }
  .adv-quarry[data-view="schema"] .adv-quarry-main, .adv-quarry[data-view="row"] .adv-quarry-main { display: none; }
  .adv-quarry[data-view="query"] .adv-quarry-main { grid-template-rows: auto minmax(0, 1fr); }
  .adv-quarry[data-view="query"] .adv-quarry-rtabs, .adv-quarry[data-view="query"] .adv-quarry-results { display: none; }
  .adv-quarry[data-view="results"] .adv-quarry-main { grid-template-rows: auto minmax(0, 1fr); }
  .adv-quarry[data-view="results"] .adv-quarry-tools, .adv-quarry[data-view="results"] .adv-quarry-editor { display: none; }
  .adv-quarry .adv-quarry-insp { position: static; grid-area: main; width: auto; translate: none; visibility: visible; box-shadow: none; border-left: 0; display: none; transition: none; }
  .adv-quarry[data-view="row"] .adv-quarry-insp { display: flex; }
  .adv-quarry .adv-quarry-foot span:nth-child(n+3) { display: none; }
  .adv-quarry .adv-quarry-rtabs { flex-wrap: wrap; padding-bottom: 4px; }
  .adv-quarry .adv-quarry-meta { margin-left: 0; width: 100%; padding: 0 9px 4px; }
}
@container adv-quarry (width < 480px) {
  .adv-quarry .adv-quarry-brand small, .adv-quarry .adv-quarry-tools .adv-quarry-btn span, .adv-quarry .adv-quarry-run kbd, .adv-quarry .adv-quarry-pos { display: none; }
  .adv-quarry .adv-quarry-foot span:nth-child(n+2) { display: none; }
  .adv-quarry .adv-quarry-plan li { grid-template-columns: 28px minmax(0, 1fr) 92px; }
}

@media (prefers-reduced-motion: reduce) {
  .adv-quarry *, .adv-quarry *::before, .adv-quarry *::after { animation-duration: .01ms !important; animation-delay: 0s !important; transition-duration: .01ms !important; transition-delay: 0s !important; }
  .adv-quarry .adv-quarry-count { transition: none; }
}

