/* ── Quarry · database browser ───────────────────────────────────────
   Four in-memory tables generated from a seeded PRNG (order totals are the
   sum of their line items), a lexer + recursive-descent parser for a useful
   SELECT subset, and an executor that reports every step it took — the Plan
   tab is the executor's own trace, not a mock. Errors carry source offsets so
   the editor can underline the exact token. */
const $ = (s, el = root) => el.querySelector(s);
const $$ = (s, el = root) => [...el.querySelectorAll(s)];
const RM = matchMedia('(prefers-reduced-motion: reduce)');
const esc = s => String(s == null ? '' : s).replace(/[&<>"']/g, c => '&#' + c.charCodeAt(0) + ';');
const isMac = /Mac|iPhone|iPad/.test(navigator.platform || navigator.userAgent || '');
const r2 = n => Math.round(n * 100) / 100;
const I = {
  chev: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="m7 10 5 5 5-5"/></svg>',
