  if (nav) { e.preventDefault(); focusCell(k + nav[0], c + nav[1], false); }
  else if (e.key === 'Home') { e.preventDefault(); focusCell(mod ? 0 : k, 0, false); }
  else if (e.key === 'End') { e.preventDefault(); focusCell(mod ? 1e6 : k, 1e6, false); }
  else if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); focusCell(k, c, true); }
});

/* first paint */
setSQL(SAVED[0][1], true);
renderSide();
run(null, { quiet: true });

css:
@property --adv-branch-len { syntax: "<number>"; inherits: true; initial-value: 0; }
.adv-branch {
  /* re-theme with these four */
  --adv-branch-bg: oklch(0.977 0.004 255);
  --adv-branch-panel: oklch(0.998 0.001 255);
  --adv-branch-ink: oklch(0.25 0.025 262);
  --adv-branch-accent: oklch(0.54 0.17 259);
  /* derived */
  --adv-branch-line: color-mix(in oklch, var(--adv-branch-ink) 10%, transparent);
  --adv-branch-line2: color-mix(in oklch, var(--adv-branch-ink) 18%, transparent);
  --adv-branch-hover: color-mix(in oklch, var(--adv-branch-ink) 4.5%, transparent);
  --adv-branch-mute: color-mix(in oklch, var(--adv-branch-ink) 68%, var(--adv-branch-bg));
  --adv-branch-faint: color-mix(in oklch, var(--adv-branch-ink) 44%, var(--adv-branch-bg));
  --adv-branch-tint: color-mix(in oklab, var(--adv-branch-accent) 10%, var(--adv-branch-panel));
  --adv-branch-tint2: color-mix(in oklab, var(--adv-branch-accent) 18%, var(--adv-branch-panel));
  --adv-branch-add: oklch(0.58 0.14 150);
  --adv-branch-del: oklch(0.57 0.18 25);
  --adv-branch-warn: oklch(0.7 0.15 70);
  --adv-branch-addbg: color-mix(in oklab, var(--adv-branch-add) 11%, var(--adv-branch-panel));
  --adv-branch-delbg: color-mix(in oklab, var(--adv-branch-del) 9%, var(--adv-branch-panel));
  --adv-branch-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  --adv-branch-ease: cubic-bezier(.2, .8, .2, 1);
  --adv-branch-spring: linear(0, 0.12 5%, 0.42 11%, 0.77 18%, 0.97 25%, 1.05 31%, 1.06 37%, 1.03 45%, 1.005 56%, 0.998 70%, 1);

  position: relative; width: 100%; height: var(--adv-branch-h, 680px); box-sizing: border-box; overflow: clip; isolation: isolate;
  container-type: inline-size; container-name: adv-branch;
  border-radius: 14px; background: var(--adv-branch-bg); color: var(--adv-branch-ink); color-scheme: light; accent-color: var(--adv-branch-accent);
  font: 13px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif; box-shadow: inset 0 0 0 1px var(--adv-branch-line);

  & *, & *::before, & *::after { box-sizing: border-box; }
  & :focus-visible { outline: 2px solid var(--adv-branch-accent); outline-offset: 1px; }
  & button, & input, & textarea { font: inherit; color: inherit; }
  & button { cursor: pointer; background: none; border: 0; padding: 0; }
  & button:disabled { cursor: not-allowed; opacity: .42; }
  & h3, & p, & ol, & ul, & dl, & dd { margin: 0; padding: 0; }
  & ol, & ul { list-style: none; }
  & [hidden] { display: none !important; }
  & svg { width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; flex: none; }
  & kbd { display: inline-grid; place-items: center; min-width: 17px; height: 17px; padding: 0 4px; border-radius: 4px; font: 600 10px/1 var(--adv-branch-mono); color: var(--adv-branch-mute); background: var(--adv-branch-panel); box-shadow: inset 0 0 0 1px var(--adv-branch-line2), 0 1px 0 var(--adv-branch-line); }
  & output { font-variant-numeric: tabular-nums; }
}
.adv-branch .adv-branch-app {
  height: 100%; display: grid; grid-template-columns: 300px minmax(0, 1fr); grid-template-rows: auto auto minmax(0, 1fr) auto;
  grid-template-areas: "top top" "mnav mnav" "side main" "foot foot";
}
.adv-branch[data-mode="history"] .adv-branch-app { grid-template-areas: "top top" "mnav mnav" "main main" "foot foot"; }
.adv-branch[data-mode="history"] .adv-branch-side { display: none; }

/* top bar */
.adv-branch .adv-branch-top { grid-area: top; display: flex; align-items: stretch; height: 54px; background: var(--adv-branch-panel); border-bottom: 1px solid var(--adv-branch-line); }
.adv-branch .adv-branch-repo, .adv-branch .adv-branch-br, .adv-branch .adv-branch-sync {
  position: relative; display: flex; align-items: center; gap: 10px; padding: 0 16px; border-right: 1px solid var(--adv-branch-line); text-align: left; min-width: 0;
  & > span { display: grid; line-height: 1.2; min-width: 0; }
  & small { font-size: 10.5px; color: var(--adv-branch-faint); white-space: nowrap; }
  & b { font-size: 13.5px; font-weight: 680; letter-spacing: -.01em; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & > svg { color: var(--adv-branch-mute); }
}
.adv-branch .adv-branch-repo { width: 300px; & > svg { color: var(--adv-branch-accent); width: 20px; height: 20px; } }
.adv-branch .adv-branch-brwrap { position: relative; display: flex; }
.adv-branch .adv-branch-br {
  min-width: 220px; transition: background .2s;
  & .chev { margin-left: auto; width: 14px; height: 14px; color: var(--adv-branch-faint); transition: rotate .3s var(--adv-branch-ease); }
  &[aria-expanded="true"] { background: var(--adv-branch-hover); }
  &[aria-expanded="true"] .chev { rotate: 180deg; }
  &:hover { background: var(--adv-branch-hover); }
}
.adv-branch .adv-branch-menu {
  position: absolute; z-index: 30; top: calc(100% + 6px); left: 8px; width: 290px; padding: 6px; border-radius: 12px; background: var(--adv-branch-panel);
  box-shadow: 0 0 0 1px var(--adv-branch-line2), 0 22px 44px -16px oklch(0.25 0.03 262 / .35);
  transform-origin: 20% 0; transition: opacity .18s, scale .3s var(--adv-branch-spring), display .3s allow-discrete;
  @starting-style { opacity: 0; scale: .95; }
  & li { display: grid; grid-template-columns: 16px minmax(0, 1fr) auto; align-items: center; gap: 9px; padding: 7px 9px; border-radius: 7px; cursor: pointer; }
  & li svg { width: 14px; height: 14px; color: var(--adv-branch-accent); opacity: 0; }
  & li[aria-selected="true"] svg { opacity: 1; }
  & li b { font: 600 12.5px var(--adv-branch-mono); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
  & li small { font-size: 11px; color: var(--adv-branch-faint); white-space: nowrap; }
  & li.is-active { background: var(--adv-branch-tint); }
  & li.h { display: block; padding: 6px 9px 4px; cursor: default; font-size: 10.5px; font-weight: 700; letter-spacing: .09em; text-transform: uppercase; color: var(--adv-branch-faint); }
}
.adv-branch .adv-branch-sync {
  overflow: hidden; display: grid; grid-template-columns: 16px auto; grid-template-rows: auto auto; column-gap: 10px; align-content: center; transition: background .2s;
  & > svg { grid-row: span 2; align-self: center; color: var(--adv-branch-accent); }
  & span { font-size: 13px; font-weight: 650; }
  &:hover:not(:disabled) { background: var(--adv-branch-hover); }
  & .adv-branch-prog { position: absolute; left: 0; right: 0; bottom: 0; height: 2px; background: var(--adv-branch-accent); transform-origin: left; scale: 0 1; }
  &.is-busy .adv-branch-prog { animation: adv-branch-prog 1.1s var(--adv-branch-ease) forwards; }
  &.is-busy > svg { animation: adv-branch-bob .9s var(--adv-branch-ease) infinite; }
}
@keyframes adv-branch-prog { to { scale: 1 1; } }
@keyframes adv-branch-bob { 50% { translate: 0 -3px; } }
.adv-branch .adv-branch-tabs {
  display: flex; align-items: stretch; margin-left: auto; padding-right: 10px;
  & button { position: relative; padding: 0 14px; font-size: 13px; font-weight: 620; color: var(--adv-branch-mute); }
  & button::after { content: ""; position: absolute; left: 12px; right: 12px; bottom: -1px; height: 2px; border-radius: 2px; background: var(--adv-branch-accent); scale: 0 1; transition: scale .35s var(--adv-branch-ease); }
  & button[aria-selected="true"] { color: var(--adv-branch-ink); }
  & button[aria-selected="true"]::after { scale: 1 1; }
  & output { display: inline-grid; place-items: center; min-width: 18px; height: 18px; padding: 0 5px; margin-left: 4px; border-radius: 9px; background: var(--adv-branch-tint2); color: var(--adv-branch-accent); font-size: 11px; font-weight: 700; }
  & output:empty { display: none; }
}
.adv-branch .adv-branch-mnav { grid-area: mnav; display: none; }

/* changed files */
.adv-branch .adv-branch-side { grid-area: side; min-height: 0; display: grid; grid-template-rows: minmax(0, 1fr) auto; border-right: 1px solid var(--adv-branch-line); background: var(--adv-branch-panel); }
.adv-branch .adv-branch-lists { min-height: 0; overflow-y: auto; scrollbar-width: thin; scrollbar-color: var(--adv-branch-line2) transparent; padding-bottom: 8px; }
.adv-branch .adv-branch-sec > header {
  position: sticky; top: 0; z-index: 1; display: flex; align-items: center; gap: 8px; height: 34px; padding: 0 10px 0 14px; background: color-mix(in oklch, var(--adv-branch-ink) 3%, var(--adv-branch-panel)); border-bottom: 1px solid var(--adv-branch-line);
  & h3 { font-size: 11.5px; font-weight: 700; letter-spacing: .02em; }
  & output { font-size: 11.5px; color: var(--adv-branch-faint); }
  & button { margin-left: auto; height: 24px; padding: 0 8px; border-radius: 6px; font-size: 11.5px; font-weight: 600; color: var(--adv-branch-accent); }
  & button:hover:not(:disabled) { background: var(--adv-branch-tint); }
}
.adv-branch .adv-branch-none { padding: 14px; font-size: 12px; color: var(--adv-branch-faint); text-wrap: pretty; }
.adv-branch .adv-branch-file {
  position: relative; display: grid; grid-template-columns: minmax(0, 1fr) 30px; align-items: center;
  & .pick { display: grid; grid-template-columns: 18px minmax(0, 1fr) auto; align-items: center; gap: 9px; height: 38px; padding: 0 4px 0 14px; text-align: left; transition: background .15s; }
  & .pick:hover { background: var(--adv-branch-hover); }
  & .pick[aria-current="true"] { background: var(--adv-branch-tint); box-shadow: inset 3px 0 0 var(--adv-branch-accent); }
  & .st { display: grid; place-items: center; width: 18px; height: 18px; border-radius: 5px; font: 700 10.5px var(--adv-branch-mono); color: var(--adv-branch-panel); background: var(--adv-branch-warn); }
  & .st[data-s="A"] { background: var(--adv-branch-add); }
  & .st[data-s="D"] { background: var(--adv-branch-del); }
  & .nm { display: grid; min-width: 0; line-height: 1.2; }
  & .nm b { font: 600 12.5px var(--adv-branch-mono); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & .nm small { font: 10.5px var(--adv-branch-mono); color: var(--adv-branch-faint); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & .ct { display: flex; gap: 5px; font: 600 11px var(--adv-branch-mono); }
  & .ct .a { color: var(--adv-branch-add); } & .ct .d { color: var(--adv-branch-del); }
  & .part { font: 600 9.5px system-ui; letter-spacing: .04em; text-transform: uppercase; color: var(--adv-branch-accent); }
  & .sb { display: grid; place-items: center; width: 24px; height: 24px; border-radius: 6px; color: var(--adv-branch-faint); box-shadow: inset 0 0 0 1px var(--adv-branch-line2); background: var(--adv-branch-panel); transition: color .2s, box-shadow .2s, background .2s; }
  & .sb svg { width: 13px; height: 13px; }
  & .sb:hover { color: var(--adv-branch-accent); box-shadow: inset 0 0 0 1px var(--adv-branch-accent); background: var(--adv-branch-tint); }
}

/* commit box */
.adv-branch .adv-branch-commit { display: grid; gap: 8px; padding: 12px 14px 14px; border-top: 1px solid var(--adv-branch-line); background: color-mix(in oklch, var(--adv-branch-ink) 2%, var(--adv-branch-panel)); margin: 0; }
.adv-branch .adv-branch-sum {
  --adv-branch-len: 0;
  position: relative; display: grid; grid-template-columns: minmax(0, 1fr) auto; align-items: center; border-radius: 8px; background: var(--adv-branch-panel); box-shadow: inset 0 0 0 1px var(--adv-branch-line2); overflow: hidden;
  transition: --adv-branch-len .35s var(--adv-branch-ease), box-shadow .2s;
  &:focus-within { box-shadow: inset 0 0 0 1.5px var(--adv-branch-accent); }
  & input { min-width: 0; height: 34px; padding: 0 10px; border: 0; outline: none; background: none; font-size: 13px; font-weight: 600; }
  & input::placeholder { font-weight: 450; color: var(--adv-branch-faint); }
  & output { padding: 0 10px; font: 600 11px var(--adv-branch-mono); color: var(--adv-branch-faint); }
  & .adv-branch-meter { position: absolute; left: 0; bottom: 0; height: 2px; width: calc(min(var(--adv-branch-len), 72) / 72 * 100%); background: var(--adv-branch-accent); border-radius: 0 2px 2px 0; }
  &[data-state="long"] .adv-branch-meter { background: var(--adv-branch-warn); }
  &[data-state="long"] output { color: color-mix(in oklch, var(--adv-branch-warn) 70%, var(--adv-branch-ink)); }
  &[data-state="over"] .adv-branch-meter { background: var(--adv-branch-del); }
  &[data-state="over"] output { color: var(--adv-branch-del); }
}
.adv-branch .adv-branch-commit textarea { width: 100%; resize: none; padding: 8px 10px; border: 0; border-radius: 8px; background: var(--adv-branch-panel); box-shadow: inset 0 0 0 1px var(--adv-branch-line2); font-size: 12.5px; line-height: 1.5; outline: none; &:focus { box-shadow: inset 0 0 0 1.5px var(--adv-branch-accent); } &::placeholder { color: var(--adv-branch-faint); } }
.adv-branch .adv-branch-amend { display: flex; align-items: center; gap: 7px; font-size: 12px; color: var(--adv-branch-mute); cursor: pointer; & input { margin: 0; } &:has(input:disabled) { opacity: .5; cursor: not-allowed; } }
.adv-branch .adv-branch-cbtn {
  height: 34px; border-radius: 8px; background: var(--adv-branch-accent); color: var(--adv-branch-panel); font-size: 13px; font-weight: 620; transition: filter .2s, scale .25s var(--adv-branch-spring), opacity .2s;
  & b { font: 700 12.5px var(--adv-branch-mono); }
  &:hover:not(:disabled) { filter: brightness(1.08); }
  &:active:not(:disabled) { scale: .97; }
}

/* diff */
.adv-branch .adv-branch-main { grid-area: main; min-width: 0; min-height: 0; display: grid; grid-template-rows: auto minmax(0, 1fr); background: var(--adv-branch-bg); }
.adv-branch .adv-branch-dhead {
  display: flex; align-items: center; gap: 10px; min-height: 46px; padding: 6px 12px 6px 16px; background: var(--adv-branch-panel); border-bottom: 1px solid var(--adv-branch-line); min-width: 0;
  & .p { flex: 1; min-width: 0; font: 12.5px var(--adv-branch-mono); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & .p span { color: var(--adv-branch-faint); }
  & .p b { font-weight: 700; }
  & .side { padding: 2px 7px; border-radius: 99px; font-size: 10.5px; font-weight: 700; letter-spacing: .04em; text-transform: uppercase; color: var(--adv-branch-accent); background: var(--adv-branch-tint); white-space: nowrap; }
  & .ct { font: 600 11.5px var(--adv-branch-mono); white-space: nowrap; }
  & .ct .a { color: var(--adv-branch-add); } & .ct .d { color: var(--adv-branch-del); }
}
.adv-branch .adv-branch-btn {
  display: inline-flex; align-items: center; gap: 6px; height: 28px; padding: 0 10px; border-radius: 7px; font-size: 12px; font-weight: 600; color: var(--adv-branch-mute); white-space: nowrap; box-shadow: inset 0 0 0 1px var(--adv-branch-line2); background: var(--adv-branch-panel); transition: color .2s, box-shadow .2s, background .2s;
  & svg { width: 14px; height: 14px; }
  &:hover:not(:disabled) { color: var(--adv-branch-ink); box-shadow: inset 0 0 0 1px var(--adv-branch-faint); }
  &[aria-pressed="true"] { color: var(--adv-branch-accent); background: var(--adv-branch-tint); box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--adv-branch-accent) 40%, transparent); }
  &.pri { color: var(--adv-branch-panel); background: var(--adv-branch-accent); box-shadow: none; }
  &.pri:hover:not(:disabled) { color: var(--adv-branch-panel); filter: brightness(1.08); box-shadow: none; }
  &.danger:hover:not(:disabled) { color: var(--adv-branch-del); box-shadow: inset 0 0 0 1px var(--adv-branch-del); }
  &.danger[data-armed] { color: var(--adv-branch-panel); background: var(--adv-branch-del); box-shadow: none; }
}
.adv-branch .adv-branch-diff { min-height: 0; overflow: auto; scrollbar-width: thin; scrollbar-color: var(--adv-branch-line2) transparent; padding: 14px 16px 30px; display: grid; align-content: start; gap: 14px; }
.adv-branch .adv-branch-hunk {
  border-radius: 10px; background: var(--adv-branch-panel); box-shadow: 0 0 0 1px var(--adv-branch-line), 0 1px 2px oklch(0.25 0.03 262 / .05); overflow: hidden; outline: none;
  transition: box-shadow .2s;
  &:focus-visible, &.is-focus { box-shadow: 0 0 0 2px var(--adv-branch-accent); }
  & > header { display: flex; align-items: center; gap: 8px; padding: 6px 8px 6px 12px; background: color-mix(in oklab, var(--adv-branch-accent) 6%, var(--adv-branch-panel)); border-bottom: 1px solid var(--adv-branch-line); min-width: 0; }
  & > header code { font: 600 11.5px var(--adv-branch-mono); color: var(--adv-branch-accent); white-space: nowrap; }
  & > header .fn { flex: 1; min-width: 0; font: 11.5px var(--adv-branch-mono); color: var(--adv-branch-faint); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & > header .adv-branch-btn { height: 26px; }
  @starting-style { opacity: 0; translate: 0 6px; }
  transition: box-shadow .2s, opacity .35s, translate .4s var(--adv-branch-ease);
}
.adv-branch .adv-branch-lines { font: 12px/20px var(--adv-branch-mono); overflow-x: auto; scrollbar-width: thin; }
.adv-branch .adv-branch-ln {
  display: grid; grid-template-columns: 42px 42px 18px minmax(max-content, 1fr); min-width: 100%;
  & .o, & .n { padding-right: 8px; text-align: right; color: color-mix(in oklch, var(--adv-branch-ink) 32%, var(--adv-branch-panel)); user-select: none; font-size: 11px; background: color-mix(in oklch, var(--adv-branch-ink) 2%, var(--adv-branch-panel)); }
  & .sg { text-align: center; color: var(--adv-branch-faint); user-select: none; }
  & code { font: inherit; white-space: pre; padding-right: 16px; }
  &.add { background: var(--adv-branch-addbg); }
  &.add .o, &.add .n { background: color-mix(in oklab, var(--adv-branch-add) 18%, var(--adv-branch-panel)); color: color-mix(in oklch, var(--adv-branch-add) 70%, var(--adv-branch-ink)); }
  &.add .sg { color: var(--adv-branch-add); }
  &.del { background: var(--adv-branch-delbg); }
  &.del .o, &.del .n { background: color-mix(in oklab, var(--adv-branch-del) 15%, var(--adv-branch-panel)); color: color-mix(in oklch, var(--adv-branch-del) 70%, var(--adv-branch-ink)); }
  &.del .sg { color: var(--adv-branch-del); }
  & mark { border-radius: 3px; color: inherit; }
  &.add mark { background: color-mix(in oklab, var(--adv-branch-add) 32%, var(--adv-branch-panel)); }
  &.del mark { background: color-mix(in oklab, var(--adv-branch-del) 28%, var(--adv-branch-panel)); }
}
.adv-branch[data-wrap="true"] .adv-branch-ln { grid-template-columns: 42px 42px 18px minmax(0, 1fr); & code { white-space: pre-wrap; word-break: break-word; } }
.adv-branch .adv-branch-empty { display: grid; place-items: center; align-content: center; gap: 8px; padding: 30px; text-align: center; color: var(--adv-branch-faint); font-size: 12.5px; text-wrap: balance; & svg { width: 40px; height: 40px; stroke-width: 1.3; color: var(--adv-branch-line2); } & b { color: var(--adv-branch-mute); font-size: 14px; } }

/* history */
.adv-branch .adv-branch-hist { grid-row: 1 / -1; min-height: 0; display: grid; grid-template-columns: minmax(0, 1.25fr) minmax(0, 1fr); }
.adv-branch .adv-branch-log { position: relative; min-height: 0; overflow-y: auto; scrollbar-width: thin; border-right: 1px solid var(--adv-branch-line); background: var(--adv-branch-panel); }
.adv-branch .adv-branch-graph { position: absolute; z-index: 1; left: 0; top: 0; width: 56px; pointer-events: none; overflow: visible; & path { fill: none; stroke-width: 2; } & circle { stroke-width: 2; } }
.adv-branch .adv-branch-commitrow {
  display: grid; grid-template-columns: minmax(0, 1fr) auto; grid-template-rows: auto auto; column-gap: 10px; align-items: center; width: 100%; height: 52px; padding: 0 14px 0 56px; text-align: left; border-bottom: 1px solid var(--adv-branch-line); transition: background .15s;
  &:hover { background: var(--adv-branch-hover); }
  &[aria-current="true"] { background: var(--adv-branch-tint); }
  & .msg { font-size: 13px; font-weight: 600; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; display: flex; gap: 6px; align-items: center; min-width: 0; }
  & .msg span { overflow: hidden; text-overflow: ellipsis; }
  & .meta { grid-column: 1; font-size: 11.5px; color: var(--adv-branch-faint); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & code { grid-row: span 2; font: 11.5px var(--adv-branch-mono); color: var(--adv-branch-faint); }
  & .ref { flex: none; padding: 1px 6px; border-radius: 5px; font: 600 10.5px var(--adv-branch-mono); color: var(--adv-branch-accent); background: var(--adv-branch-tint2); }
  & .ref.remote { color: var(--adv-branch-mute); background: var(--adv-branch-hover); box-shadow: inset 0 0 0 1px var(--adv-branch-line2); }
  & .ref.tag { color: color-mix(in oklch, var(--adv-branch-warn) 60%, var(--adv-branch-ink)); background: color-mix(in oklab, var(--adv-branch-warn) 18%, var(--adv-branch-panel)); }
  & .ahead { flex: none; font: 700 10px system-ui; letter-spacing: .05em; text-transform: uppercase; color: var(--adv-branch-warn); }
  @starting-style { opacity: 0; translate: 0 -10px; background: var(--adv-branch-tint2); }
  transition: background .6s, opacity .4s, translate .5s var(--adv-branch-spring);
}
