/* ── Branchwork · git client ─────────────────────────────────────────
   The working tree is a list of files, each a list of hunks with a staged
   flag. "Unstaged" and "Staged" are two filters over that one model, so a
   partly staged file appears in both lists, exactly like git's index. Hunk
   headers and line numbers are computed from the hunks, never typed in.
   Rows and hunks carry a data-flip key and move with a WAAPI FLIP. */
const $ = (s, el = root) => el.querySelector(s);
