    HK(41, 'export function invoiceTotal(items: LineItem[])', `
   return items.reduce((sum, i) => sum + lineTotal(i), 0);
 }

+export function formatMoney(cents: number, currency = 'EUR'): string {
+  return new Intl.NumberFormat('en-IE', {
+    style: 'currency',
