/* ── history ── */
const PEOPLE = { mina: ['Mina Sato', 'oklch(0.6 0.14 30)'], joel: ['Joel Ferreira', 'oklch(0.55 0.12 160)'], ada: ['Ada Lindqvist', 'oklch(0.56 0.13 300)'], you: ['Rafa Quint', 'oklch(0.54 0.17 259)'] };
const NOW = Date.now();
const CM = (hash, msg, who, agoMin, files, o) => Object.assign({ hash, msg, who, at: NOW - agoMin * 60000, files, lane: 0, parents: [], body: '' }, o || {});
const BASE = [
  CM('a3f9c21', 'Add usage endpoint for the quota hook', 'mina', 128, [['src/api/usage.ts', 'A', 38, 0], ['src/api/index.ts', 'M', 2, 0]], { parents: ['7be04d8'], body: 'GET /api/usage returns used, limit and resetsAt for the signed-in team.' }),
  CM('7be04d8', "Merge branch 'fix/tz-rounding'", 'joel', 310, [['src/billing/dates.ts', 'M', 14, 6], ['src/billing/__tests__/dates.test.ts', 'M', 22, 0]], { parents: ['e98a0b7', '51c2e9a'], merge: true }),
  CM('51c2e9a', "Round invoice dates to the customer's time zone", 'ada', 1560, [['src/billing/dates.ts', 'M', 14, 6], ['src/billing/__tests__/dates.test.ts', 'M', 22, 0]], { parents: ['0c4d1f3'], lane: 1, body: 'Invoices issued after 23:00 UTC were dated the next day for customers west of Greenwich.' }),
