  CM('0c4d1f3', 'Show the plan name in the account menu', 'mina', 4320, [['src/components/AccountMenu.tsx', 'M', 9, 2]], { parents: ['9d7a6e2'] }),
  CM('9d7a6e2', 'Release 4.12.0', 'ada', 5790, [['package.json', 'M', 1, 1], ['CHANGELOG.md', 'M', 17, 0]], { tag: 'v4.12.0' }),
