  if (RM.matches) return;
  $$('[data-flip]').forEach(el => {
    const k = el.dataset.flip;
    let b = before.get(k);
    if (!b && k.startsWith('f:')) b = before.get(k.endsWith('|staged') ? k.replace(/\|staged$/, '|unstaged') : k.replace(/\|unstaged$/, '|staged'));
