  --adv-pennant-hover: color-mix(in oklch, var(--adv-pennant-ink) 5%, transparent);
  --adv-pennant-mute: color-mix(in oklch, var(--adv-pennant-ink) 68%, var(--adv-pennant-bg));
  --adv-pennant-faint: color-mix(in oklch, var(--adv-pennant-ink) 45%, var(--adv-pennant-bg));
  --adv-pennant-tint: color-mix(in oklab, var(--adv-pennant-accent) 11%, var(--adv-pennant-panel));
  --adv-pennant-tint2: color-mix(in oklab, var(--adv-pennant-accent) 20%, var(--adv-pennant-panel));
  --adv-pennant-dev: oklch(0.62 0.13 150);
  --adv-pennant-stg: oklch(0.72 0.14 72);
  --adv-pennant-prd: oklch(0.6 0.17 27);
  --adv-pennant-envc: var(--adv-pennant-prd);
  --adv-pennant-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  --adv-pennant-ease: cubic-bezier(.2, .8, .2, 1);
  --adv-pennant-spring: linear(0, 0.12 5%, 0.42 11%, 0.77 18%, 0.97 25%, 1.05 31%, 1.06 37%, 1.03 45%, 1.005 56%, 0.998 70%, 1);

  position: relative; width: 100%; height: var(--adv-pennant-h, 680px); box-sizing: border-box; overflow: clip; isolation: isolate;
  container-type: inline-size; container-name: adv-pennant;
  border-radius: 14px; background: var(--adv-pennant-bg); color: var(--adv-pennant-ink); color-scheme: light; accent-color: var(--adv-pennant-accent);
  font: 13px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif; box-shadow: inset 0 0 0 1px var(--adv-pennant-line);

  &[data-env="development"] { --adv-pennant-envc: var(--adv-pennant-dev); }
  &[data-env="staging"] { --adv-pennant-envc: var(--adv-pennant-stg); }
  & *, & *::before, & *::after { box-sizing: border-box; }
  & :focus-visible { outline: 2px solid var(--adv-pennant-accent); outline-offset: 1px; }
  & button, & input, & select, & textarea { font: inherit; color: inherit; }
  & button { cursor: pointer; background: none; border: 0; padding: 0; }
  & button:disabled { cursor: not-allowed; opacity: .42; }
  & h2, & h3, & h4, & p, & ol, & ul, & dl, & dd { margin: 0; padding: 0; }
  & ol, & ul { list-style: none; }
  & [hidden] { display: none !important; }
  & svg { width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; flex: none; }
  & kbd { display: inline-grid; place-items: center; min-width: 17px; height: 17px; padding: 0 4px; border-radius: 4px; font: 600 10px/1 var(--adv-pennant-mono); color: var(--adv-pennant-mute); background: var(--adv-pennant-panel); box-shadow: inset 0 0 0 1px var(--adv-pennant-line2), 0 1px 0 var(--adv-pennant-line); }
  & output { font-variant-numeric: tabular-nums; }
  & select, & input:not([type="checkbox"]):not([type="search"]) { height: 30px; padding: 0 8px; border: 0; border-radius: 7px; background: var(--adv-pennant-panel); box-shadow: inset 0 0 0 1px var(--adv-pennant-line2); font-size: 12.5px; outline: none; min-width: 0; }
  & select:focus, & input:not([type="checkbox"]):not([type="search"]):focus { box-shadow: inset 0 0 0 1.5px var(--adv-pennant-accent); }
  & select { appearance: none; padding-right: 24px; cursor: pointer; background-image: linear-gradient(45deg, transparent 50%, var(--adv-pennant-faint) 50%), linear-gradient(135deg, var(--adv-pennant-faint) 50%, transparent 50%); background-position: calc(100% - 13px) 55%, calc(100% - 9px) 55%; background-size: 4px 4px; background-repeat: no-repeat; text-overflow: ellipsis; }
}
.adv-pennant .adv-pennant-app {
  height: 100%; display: grid; grid-template-columns: 252px minmax(0, 1fr) 292px; grid-template-rows: auto auto minmax(0, 1fr) auto;
  grid-template-areas: "top top top" "mnav mnav mnav" "side main eval" "foot foot foot";
}

/* top */
.adv-pennant .adv-pennant-top { grid-area: top; display: flex; align-items: center; gap: 14px; padding: 10px 14px 10px 16px; border-bottom: 1px solid var(--adv-pennant-line); background: var(--adv-pennant-panel); }
.adv-pennant .adv-pennant-brand {
  display: flex; align-items: center; gap: 10px; margin-right: auto; min-width: 0;
  & svg { width: 24px; height: 24px; color: var(--adv-pennant-accent); }
  & span { display: grid; line-height: 1.15; min-width: 0; }
  & b { font-size: 15px; font-weight: 760; letter-spacing: -.02em; }
  & small { font-size: 11px; color: var(--adv-pennant-faint); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
}
.adv-pennant .adv-pennant-envs {
  display: flex; gap: 2px; padding: 3px; border-radius: 10px; background: color-mix(in oklch, var(--adv-pennant-ink) 6%, var(--adv-pennant-bg));
  & button { display: inline-flex; align-items: center; gap: 7px; height: 28px; padding: 0 11px; border-radius: 7px; font-size: 12px; font-weight: 640; color: var(--adv-pennant-mute); transition: background .2s, color .2s, box-shadow .2s; }
  & i { width: 7px; height: 7px; border-radius: 50%; background: var(--c); }
  & [data-env="development"] { --c: var(--adv-pennant-dev); } & [data-env="staging"] { --c: var(--adv-pennant-stg); } & [data-env="production"] { --c: var(--adv-pennant-prd); }
  & button[aria-selected="true"] { background: var(--adv-pennant-panel); color: var(--adv-pennant-ink); box-shadow: 0 1px 2px oklch(0 0 0 / .1), 0 0 0 1px var(--adv-pennant-line), inset 0 -2px 0 var(--c); }
  & button:hover:not([aria-selected="true"]) { color: var(--adv-pennant-ink); }
}
.adv-pennant .adv-pennant-btn {
  display: inline-flex; align-items: center; gap: 6px; height: 30px; padding: 0 11px; border-radius: 8px; font-size: 12.5px; font-weight: 620; color: var(--adv-pennant-mute); white-space: nowrap;
  box-shadow: inset 0 0 0 1px var(--adv-pennant-line2); background: var(--adv-pennant-panel); transition: color .2s, box-shadow .2s, background .2s, filter .2s;
  & svg { width: 15px; height: 15px; }
  &:hover:not(:disabled), &[aria-expanded="true"] { color: var(--adv-pennant-ink); box-shadow: inset 0 0 0 1px var(--adv-pennant-faint); }
  &.pri { background: var(--adv-pennant-accent); color: var(--adv-pennant-panel); box-shadow: none; }
  &.pri:hover:not(:disabled) { filter: brightness(1.08); color: var(--adv-pennant-panel); box-shadow: none; }
  &.sm { height: 26px; padding: 0 8px; font-size: 12px; }
  &.ghost { box-shadow: none; background: none; }
  &.ghost:hover:not(:disabled) { background: var(--adv-pennant-hover); box-shadow: none; }
}
.adv-pennant .adv-pennant-evalbtn { display: none; }
.adv-pennant .adv-pennant-mnav { grid-area: mnav; display: none; }

/* flag list */
.adv-pennant .adv-pennant-side { grid-area: side; min-height: 0; display: flex; flex-direction: column; gap: 10px; padding: 12px 10px 10px; border-right: 1px solid var(--adv-pennant-line); }
.adv-pennant .adv-pennant-search {
  display: flex; align-items: center; gap: 7px; height: 32px; padding: 0 6px 0 10px; border-radius: 9px; background: var(--adv-pennant-panel); box-shadow: inset 0 0 0 1px var(--adv-pennant-line2); cursor: text; transition: box-shadow .2s;
  & svg { color: var(--adv-pennant-faint); }
  & input { flex: 1; min-width: 0; height: 100%; border: 0; outline: none; background: none; font-size: 12.5px; }
  & input::-webkit-search-cancel-button { display: none; }
  &:focus-within { box-shadow: inset 0 0 0 1.5px var(--adv-pennant-accent); }
}
.adv-pennant .adv-pennant-chips {
  display: flex; flex-wrap: wrap; gap: 4px;
  & button { height: 24px; padding: 0 9px; border-radius: 99px; font-size: 11.5px; font-weight: 620; color: var(--adv-pennant-mute); box-shadow: inset 0 0 0 1px var(--adv-pennant-line2); transition: background .2s, color .2s; }
  & button[aria-checked="true"] { background: var(--adv-pennant-ink); color: var(--adv-pennant-panel); box-shadow: none; }
  & output { margin-left: 4px; font-size: 10.5px; opacity: .7; }
}
.adv-pennant .adv-pennant-flags { flex: 1; min-height: 0; overflow-y: auto; scrollbar-width: thin; scrollbar-color: var(--adv-pennant-line2) transparent; display: grid; align-content: start; gap: 2px; }
.adv-pennant .adv-pennant-flag {
  position: relative; display: grid; grid-template-columns: minmax(0, 1fr) auto; align-items: center; gap: 8px; border-radius: 9px; transition: background .18s;
  &:hover { background: var(--adv-pennant-hover); }
  &:has(.pick[aria-selected="true"]) { background: var(--adv-pennant-panel); box-shadow: 0 0 0 1px var(--adv-pennant-line2), 0 2px 6px -3px oklch(0.25 0.03 165 / .2); }
  & .pick { display: grid; gap: 1px; padding: 8px 0 8px 10px; text-align: left; min-width: 0; }
  & .pick b { font-size: 12.5px; font-weight: 650; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & .pick code { font: 11px var(--adv-pennant-mono); color: var(--adv-pennant-faint); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & .pick small { display: flex; gap: 6px; align-items: center; margin-top: 3px; font-size: 10.5px; color: var(--adv-pennant-faint); }
  & .stale { padding: 0 5px; border-radius: 4px; font-weight: 700; letter-spacing: .03em; text-transform: uppercase; font-size: 9.5px; color: oklch(0.5 0.12 70); background: color-mix(in oklab, var(--adv-pennant-stg) 22%, var(--adv-pennant-panel)); }
  & .dirty { width: 6px; height: 6px; border-radius: 50%; background: var(--adv-pennant-stg); }
  animation: adv-pennant-rise .35s var(--adv-pennant-ease) backwards; animation-delay: calc(var(--i) * 30ms);
}
@keyframes adv-pennant-rise { from { opacity: 0; translate: 0 5px; } }
.adv-pennant .adv-pennant-switch {
  position: relative; width: 34px; height: 20px; margin-right: 10px; border-radius: 99px; background: color-mix(in oklch, var(--adv-pennant-ink) 18%, var(--adv-pennant-bg)); transition: background .3s;
  &::after { content: ""; position: absolute; top: 2px; left: 2px; width: 16px; height: 16px; border-radius: 50%; background: var(--adv-pennant-panel); box-shadow: 0 1px 3px oklch(0 0 0 / .25); transition: translate .4s var(--adv-pennant-spring); }
  &[aria-checked="true"] { background: var(--adv-pennant-accent); }
  &[aria-checked="true"]::after { translate: 14px 0; }
  &.lg { width: 44px; height: 26px; margin: 0; }
  &.lg::after { width: 22px; height: 22px; }
  &.lg[aria-checked="true"]::after { translate: 18px 0; }
}
.adv-pennant .adv-pennant-none { padding: 14px 10px; font-size: 12px; color: var(--adv-pennant-faint); text-wrap: pretty; }

/* detail */
.adv-pennant .adv-pennant-main { grid-area: main; min-width: 0; min-height: 0; display: grid; grid-template-rows: minmax(0, 1fr) auto; }
.adv-pennant .adv-pennant-scroll { min-height: 0; overflow-y: auto; scrollbar-width: thin; scrollbar-color: var(--adv-pennant-line2) transparent; padding: 18px clamp(14px, 2.4cqi, 26px) 28px; display: grid; align-content: start; gap: 18px; }
.adv-pennant .adv-pennant-head {
  display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 4px 16px; align-items: start;
  & h2 { font-size: clamp(18px, 2cqi, 22px); font-weight: 760; letter-spacing: -.025em; line-height: 1.15; text-wrap: balance; }
  & p { grid-column: 1; font-size: 12.5px; color: var(--adv-pennant-mute); text-wrap: pretty; max-width: 60ch; }
  & .key { grid-column: 1; display: flex; flex-wrap: wrap; align-items: center; gap: 6px; margin-top: 4px; }
  & .key code { font: 600 12px var(--adv-pennant-mono); color: var(--adv-pennant-accent); }
  & .tag { padding: 1px 7px; border-radius: 99px; font-size: 11px; color: var(--adv-pennant-mute); box-shadow: inset 0 0 0 1px var(--adv-pennant-line2); }
  & .kind { padding: 1px 7px; border-radius: 5px; font: 600 10.5px var(--adv-pennant-mono); color: var(--adv-pennant-panel); background: var(--adv-pennant-ink); }
}
.adv-pennant .adv-pennant-onoff {
  grid-row: 1 / span 3; grid-column: 2; display: grid; justify-items: end; gap: 6px; padding: 10px 12px; border-radius: 12px; background: var(--adv-pennant-panel); box-shadow: 0 0 0 1px var(--adv-pennant-line), inset 0 3px 0 var(--adv-pennant-envc);
  & small { font-size: 10.5px; font-weight: 700; letter-spacing: .08em; text-transform: uppercase; color: var(--adv-pennant-faint); white-space: nowrap; }
  & span { display: flex; align-items: center; gap: 10px; font-size: 13px; font-weight: 700; }
}
.adv-pennant .adv-pennant-warn { display: flex; gap: 10px; padding: 10px 12px; border-radius: 10px; font-size: 12.5px; background: color-mix(in oklab, var(--adv-pennant-stg) 14%, var(--adv-pennant-panel)); box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--adv-pennant-stg) 40%, transparent); text-wrap: pretty; & svg { color: oklch(0.55 0.13 70); margin-top: 1px; } }
.adv-pennant .adv-pennant-sec { display: grid; gap: 10px; }
.adv-pennant .adv-pennant-sech { display: flex; align-items: baseline; gap: 10px; & h3 { font-size: 11px; font-weight: 750; letter-spacing: .09em; text-transform: uppercase; color: var(--adv-pennant-faint); } & small { font-size: 11.5px; color: var(--adv-pennant-faint); } & .adv-pennant-btn { margin-left: auto; } }
.adv-pennant .adv-pennant-vars { display: flex; flex-wrap: wrap; gap: 6px; }
.adv-pennant .adv-pennant-var { display: inline-flex; align-items: center; gap: 7px; height: 28px; padding: 0 10px 0 8px; border-radius: 8px; background: var(--adv-pennant-panel); box-shadow: inset 0 0 0 1px var(--adv-pennant-line); font-size: 12.5px; font-weight: 600; & i { width: 10px; height: 10px; border-radius: 3px; background: var(--c); } & code { font: 11.5px var(--adv-pennant-mono); color: var(--adv-pennant-faint); } }
.adv-pennant .adv-pennant-targets { display: grid; gap: 6px; }
.adv-pennant .adv-pennant-trow {
  display: grid; grid-template-columns: 120px minmax(0, 1fr); align-items: center; gap: 10px; padding: 8px 10px; border-radius: 10px; background: var(--adv-pennant-panel); box-shadow: inset 0 0 0 1px var(--adv-pennant-line);
  & > span { display: flex; align-items: center; gap: 7px; font-size: 12.5px; font-weight: 600; }
  & > span i { width: 10px; height: 10px; border-radius: 3px; background: var(--c); }
  & .chips { display: flex; flex-wrap: wrap; align-items: center; gap: 5px; }
  & .chip { display: inline-flex; align-items: center; gap: 4px; height: 24px; padding: 0 4px 0 8px; border-radius: 6px; background: var(--adv-pennant-hover); font: 11.5px var(--adv-pennant-mono); transition: opacity .25s, scale .3s var(--adv-pennant-spring); @starting-style { opacity: 0; scale: .8; } }
  & .chip button { display: grid; place-items: center; width: 18px; height: 18px; border-radius: 4px; color: var(--adv-pennant-faint); }
  & .chip button:hover { color: var(--adv-pennant-prd); background: var(--adv-pennant-hover); }
  & .chip button svg { width: 11px; height: 11px; }
  & input { width: 130px; height: 24px !important; font: 11.5px var(--adv-pennant-mono) !important; }
}
.adv-pennant .adv-pennant-rules { display: grid; gap: 8px; }
.adv-pennant .adv-pennant-rule {
  position: relative; display: grid; gap: 8px; padding: 10px 12px 12px; border-radius: 12px; background: var(--adv-pennant-panel); box-shadow: inset 0 0 0 1px var(--adv-pennant-line); outline: none;
  transition: box-shadow .25s;
  &:focus-visible { box-shadow: inset 0 0 0 2px var(--adv-pennant-accent); }
  & > header { display: flex; align-items: center; gap: 8px; min-width: 0; }
  & .n { display: grid; place-items: center; width: 22px; height: 22px; border-radius: 6px; font: 700 11px var(--adv-pennant-mono); color: var(--adv-pennant-accent); background: var(--adv-pennant-tint); flex: none; }
  & .t { flex: 1; min-width: 0; height: 26px !important; padding: 0 6px !important; box-shadow: none !important; background: none !important; font-size: 13px !important; font-weight: 680; }
  & .t:focus { box-shadow: inset 0 0 0 1.5px var(--adv-pennant-accent) !important; }
  & .mv { display: grid; place-items: center; width: 26px; height: 26px; border-radius: 6px; color: var(--adv-pennant-faint); }
  & .mv:hover:not(:disabled) { background: var(--adv-pennant-hover); color: var(--adv-pennant-ink); }
  & .mv svg { width: 14px; height: 14px; }
  & .mv.del:hover:not(:disabled) { color: var(--adv-pennant-prd); }
  & .cl { display: grid; grid-template-columns: 34px minmax(90px, .8fr) minmax(110px, .9fr) minmax(0, 1.4fr) 26px; align-items: center; gap: 6px; }
  & .cl b { font: 700 10.5px var(--adv-pennant-mono); color: var(--adv-pennant-faint); text-align: right; }
  & .serve { display: grid; grid-template-columns: 34px minmax(0, 220px); align-items: center; gap: 6px; }
  & .serve b { font: 700 10.5px var(--adv-pennant-mono); color: var(--adv-pennant-accent); text-align: right; }
  & .addcl { justify-self: start; margin-left: 40px; }
  &::after { content: ""; position: absolute; inset: 0; border-radius: inherit; pointer-events: none; box-shadow: 0 0 0 var(--adv-pennant-ring) color-mix(in oklch, var(--adv-pennant-accent) 30%, transparent); opacity: 0; }
  &.is-hit { box-shadow: inset 0 0 0 1.5px var(--adv-pennant-accent), 0 4px 14px -6px color-mix(in oklch, var(--adv-pennant-accent) 50%, transparent); }
  &.is-hit::after { animation: adv-pennant-ping 1.6s var(--adv-pennant-ease) 2; }
  & .hit { display: none; padding: 1px 7px; border-radius: 99px; font-size: 10.5px; font-weight: 700; color: var(--adv-pennant-panel); background: var(--adv-pennant-accent); white-space: nowrap; }
  &.is-hit .hit { display: inline-block; }
}
@keyframes adv-pennant-ping { from { --adv-pennant-ring: 0px; opacity: 1; } to { --adv-pennant-ring: 10px; opacity: 0; } }
.adv-pennant .adv-pennant-fall {
  display: grid; gap: 10px; padding: 12px; border-radius: 12px; background: var(--adv-pennant-panel); box-shadow: inset 0 0 0 1px var(--adv-pennant-line);
  &.is-hit { box-shadow: inset 0 0 0 1.5px var(--adv-pennant-accent); }
  & .row { display: flex; flex-wrap: wrap; align-items: center; gap: 8px; font-size: 12.5px; }
  & .row b { font: 700 10.5px var(--adv-pennant-mono); color: var(--adv-pennant-accent); }
}
.adv-pennant .adv-pennant-split {
  display: flex; height: 30px; border-radius: 8px; overflow: hidden; gap: 2px; background: var(--adv-pennant-line);
  & span { --adv-pennant-p: 0; flex: var(--adv-pennant-p) 1 0; min-width: 0; display: flex; align-items: center; padding: 0 8px; background: var(--c); color: oklch(1 0 0); font: 700 11.5px var(--adv-pennant-mono); white-space: nowrap; overflow: hidden; transition: --adv-pennant-p .55s var(--adv-pennant-spring); }
  & span[data-zero] { padding: 0; }
}
.adv-pennant .adv-pennant-weights { display: flex; flex-wrap: wrap; gap: 8px; & label { display: inline-flex; align-items: center; gap: 6px; font-size: 12px; } & label i { width: 10px; height: 10px; border-radius: 3px; background: var(--c); } & input { width: 64px; text-align: right; font-variant-numeric: tabular-nums; } & .sum { align-self: center; font-size: 12px; color: var(--adv-pennant-faint); } & .sum.bad { color: var(--adv-pennant-prd); font-weight: 650; } }
.adv-pennant .adv-pennant-sim { display: grid; gap: 5px; font-size: 11.5px; color: var(--adv-pennant-faint); & div { display: grid; grid-template-columns: 90px minmax(0, 1fr) 54px; align-items: center; gap: 8px; } & i { display: block; height: 6px; border-radius: 3px; background: var(--c); transform-origin: left; scale: var(--s) 1; transition: scale .6s var(--adv-pennant-ease); } & output { text-align: right; font-family: var(--adv-pennant-mono); color: var(--adv-pennant-mute); } }

/* save bar */
.adv-pennant .adv-pennant-savebar {
  display: flex; align-items: center; gap: 10px; padding: 10px 16px; border-top: 1px solid var(--adv-pennant-line); background: var(--adv-pennant-panel); font-size: 12.5px;
  &:empty { display: none; }
  & .dot { width: 8px; height: 8px; border-radius: 50%; background: var(--adv-pennant-stg); box-shadow: 0 0 0 3px color-mix(in oklch, var(--adv-pennant-stg) 25%, transparent); }
  & b { font-weight: 700; }
  & .sp { flex: 1; }
  transition: opacity .3s, translate .4s var(--adv-pennant-spring);
  @starting-style { opacity: 0; translate: 0 12px; }
}

/* evaluate */
.adv-pennant .adv-pennant-eval { grid-area: eval; min-height: 0; display: grid; grid-template-rows: auto minmax(0, 1fr); border-left: 1px solid var(--adv-pennant-line); background: color-mix(in oklch, var(--adv-pennant-panel) 55%, var(--adv-pennant-bg)); }
.adv-pennant .adv-pennant-etabs {
  display: flex; padding: 0 10px; border-bottom: 1px solid var(--adv-pennant-line);
