css:
.adv-sieve {
  /* re-theme with these four */
  --adv-sieve-bg: oklch(0.965 0.02 92);
  --adv-sieve-panel: oklch(0.985 0.012 92);
  --adv-sieve-ink: oklch(0.23 0.012 70);
  --adv-sieve-accent: oklch(0.88 0.165 98);
  /* derived */
  --adv-sieve-line: color-mix(in oklch, var(--adv-sieve-ink) 12%, transparent);
  --adv-sieve-line2: color-mix(in oklch, var(--adv-sieve-ink) 22%, transparent);
  --adv-sieve-hover: color-mix(in oklch, var(--adv-sieve-ink) 5%, transparent);
  --adv-sieve-mute: color-mix(in oklch, var(--adv-sieve-ink) 68%, var(--adv-sieve-bg));
  --adv-sieve-faint: color-mix(in oklch, var(--adv-sieve-ink) 45%, var(--adv-sieve-bg));
  --adv-sieve-pen: oklch(0.52 0.17 28);
  --adv-sieve-ok: oklch(0.52 0.12 150);
  --adv-sieve-g1: oklch(0.89 0.13 95);
  --adv-sieve-g2: oklch(0.86 0.08 350);
  --adv-sieve-g3: oklch(0.87 0.065 230);
  --adv-sieve-g4: oklch(0.88 0.09 150);
  --adv-sieve-g5: oklch(0.87 0.09 55);
  --adv-sieve-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  --adv-sieve-ease: cubic-bezier(.2, .8, .2, 1);
  --adv-sieve-spring: linear(0, 0.12 5%, 0.42 11%, 0.77 18%, 0.97 25%, 1.05 31%, 1.06 37%, 1.03 45%, 1.005 56%, 0.998 70%, 1);

  position: relative; width: 100%; height: var(--adv-sieve-h, 680px); box-sizing: border-box; overflow: clip; isolation: isolate;
  container-type: inline-size; container-name: adv-sieve;
  border-radius: 14px; background: var(--adv-sieve-bg); color: var(--adv-sieve-ink); color-scheme: light; accent-color: var(--adv-sieve-ink);
  font: 13px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif; box-shadow: inset 0 0 0 1px var(--adv-sieve-line);

  & *, & *::before, & *::after { box-sizing: border-box; }
  & :focus-visible { outline: 2px solid var(--adv-sieve-ink); outline-offset: 1px; }
  & button, & input, & textarea { font: inherit; color: inherit; }
  & button { cursor: pointer; background: none; border: 0; padding: 0; }
  & button:disabled { cursor: not-allowed; opacity: .4; }
  & h3, & p, & ol, & ul, & dl, & dd { margin: 0; padding: 0; }
  & ol, & ul { list-style: none; }
  & [hidden] { display: none !important; }
  & svg { width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; flex: none; }
  & kbd { display: inline-grid; place-items: center; min-width: 17px; height: 17px; padding: 0 4px; border-radius: 4px; font: 600 10px/1 var(--adv-sieve-mono); color: var(--adv-sieve-mute); background: var(--adv-sieve-panel); box-shadow: inset 0 0 0 1px var(--adv-sieve-line2), 0 1px 0 var(--adv-sieve-line); }
  & output { font-variant-numeric: tabular-nums; }
  & code { font-family: var(--adv-sieve-mono); }
  & .g1 { --g: var(--adv-sieve-g1); } & .g2 { --g: var(--adv-sieve-g2); } & .g3 { --g: var(--adv-sieve-g3); } & .g4 { --g: var(--adv-sieve-g4); } & .g5 { --g: var(--adv-sieve-g5); }
}
.adv-sieve .adv-sieve-app {
  height: 100%; display: grid; grid-template-columns: 206px minmax(0, 1fr) 318px; grid-template-rows: auto auto minmax(0, 1fr) auto;
  grid-template-areas: "top top top" "mnav mnav mnav" "lib work side" "foot foot foot";
}
.adv-sieve .adv-sieve-top { grid-area: top; display: flex; align-items: center; gap: 12px; padding: 10px 16px; border-bottom: 1px solid var(--adv-sieve-line); }
.adv-sieve .adv-sieve-brand {
  display: flex; align-items: center; gap: 10px; margin-right: auto; min-width: 0;
  & svg { width: 26px; height: 26px; padding: 4px; border-radius: 7px; background: var(--adv-sieve-accent); stroke-width: 1.8; }
  & span { display: grid; line-height: 1.15; min-width: 0; }
  & b { font-size: 15px; font-weight: 800; letter-spacing: -.02em; }
  & small { font-size: 11px; color: var(--adv-sieve-faint); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
}
.adv-sieve .adv-sieve-badge {
  display: inline-flex; align-items: center; gap: 7px; height: 28px; padding: 0 12px; border-radius: 99px; font: 700 12px var(--adv-sieve-mono); background: var(--adv-sieve-accent);
  &.is-none { background: var(--adv-sieve-hover); color: var(--adv-sieve-mute); }
  &.is-err { background: color-mix(in oklab, var(--adv-sieve-pen) 14%, var(--adv-sieve-panel)); color: var(--adv-sieve-pen); }
  &.is-bump { animation: adv-sieve-bump .45s var(--adv-sieve-spring); }
}
@keyframes adv-sieve-bump { 40% { scale: 1.08; } }
.adv-sieve .adv-sieve-mnav { grid-area: mnav; display: none; }

/* library */
.adv-sieve .adv-sieve-lib {
  grid-area: lib; min-height: 0; overflow-y: auto; scrollbar-width: thin; padding: 14px 10px; border-right: 1px solid var(--adv-sieve-line); display: flex; flex-direction: column; gap: 8px;
  & h3 { padding: 0 8px; font-size: 10.5px; font-weight: 750; letter-spacing: .1em; text-transform: uppercase; color: var(--adv-sieve-faint); }
  & ul { display: grid; gap: 2px; }
  & button { display: grid; gap: 2px; width: 100%; padding: 7px 9px; border-radius: 8px; text-align: left; transition: background .18s; }
  & button:hover { background: var(--adv-sieve-hover); }
  & button[aria-current="true"] { background: var(--adv-sieve-panel); box-shadow: 0 0 0 1px var(--adv-sieve-line2), inset 3px 0 0 var(--adv-sieve-accent); }
  & b { font-size: 12.5px; font-weight: 650; }
  & code { font-size: 10.5px; color: var(--adv-sieve-faint); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & .adv-sieve-tip { margin-top: auto; padding: 10px; border-radius: 9px; font-size: 11.5px; color: var(--adv-sieve-mute); background: var(--adv-sieve-hover); text-wrap: pretty; }
  & .adv-sieve-tip code { font-size: 11px; padding: 0 3px; border-radius: 3px; background: var(--adv-sieve-accent); color: var(--adv-sieve-ink); }
}

/* pattern */
.adv-sieve .adv-sieve-work { grid-area: work; min-width: 0; min-height: 0; display: grid; grid-template-columns: minmax(0, 1fr); grid-template-rows: auto minmax(0, 1fr); }
.adv-sieve .adv-sieve-patrow { padding: 14px 16px 10px; border-bottom: 1px solid var(--adv-sieve-line); background: var(--adv-sieve-panel); }
.adv-sieve .adv-sieve-pat {
  display: flex; align-items: center; gap: 2px; min-width: 0; height: 46px; padding: 0 6px 0 12px; border-radius: 11px; background: var(--adv-sieve-bg); box-shadow: inset 0 0 0 1.5px var(--adv-sieve-line2); transition: box-shadow .2s;
  &:focus-within { box-shadow: inset 0 0 0 2px var(--adv-sieve-ink); }
  &:has(.field.is-bad) { box-shadow: inset 0 0 0 2px var(--adv-sieve-pen); }
  & .sl { font: 600 17px var(--adv-sieve-mono); color: var(--adv-sieve-faint); }
  & .field { position: relative; flex: 1; min-width: 0; height: 100%; }
  & input, & .mirror { position: absolute; inset: 0; width: 100%; height: 100%; padding: 0 4px; border: 0; font: 500 15px/46px var(--adv-sieve-mono); white-space: pre; letter-spacing: 0; }
  & input { background: transparent; color: transparent; caret-color: var(--adv-sieve-ink); outline: none; }
  & input::selection { background: color-mix(in oklch, var(--adv-sieve-ink) 18%, transparent); color: transparent; }
  & .mirror { overflow: hidden; pointer-events: none; }
  & .mirror span { border-radius: 3px; transition: background .2s, box-shadow .2s; }
  & .t-grp { color: var(--c, var(--adv-sieve-ink)); font-weight: 750; }
  & .t-cls { background: color-mix(in oklch, var(--adv-sieve-g3) 55%, transparent); }
  & .t-q { color: var(--adv-sieve-pen); font-weight: 700; }
  & .t-esc { color: oklch(0.45 0.13 250); }
  & .t-anc { color: oklch(0.45 0.15 310); font-weight: 700; }
  & .t-alt { color: var(--adv-sieve-pen); font-weight: 800; }
  & .t-dot { color: oklch(0.45 0.13 250); font-weight: 800; }
  & .is-hot { background: var(--adv-sieve-accent) !important; box-shadow: 0 0 0 2px var(--adv-sieve-accent); }
  & .field.is-bad .mirror { text-decoration: wavy underline var(--adv-sieve-pen); text-underline-offset: 6px; }
}
.adv-sieve .adv-sieve-flags {
  display: flex; gap: 2px; margin-left: 6px;
  & button { display: grid; place-items: center; width: 26px; height: 30px; border-radius: 7px; font: 700 13px var(--adv-sieve-mono); color: var(--adv-sieve-faint); transition: background .2s, color .2s, scale .3s var(--adv-sieve-spring); }
  & button:hover { color: var(--adv-sieve-ink); background: var(--adv-sieve-hover); }
  & button[aria-pressed="true"] { background: var(--adv-sieve-ink); color: var(--adv-sieve-accent); }
  & button:active { scale: .9; }
}
.adv-sieve .adv-sieve-perr { min-height: 18px; padding: 6px 4px 0; font-size: 12px; color: var(--adv-sieve-faint); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; & b { color: var(--adv-sieve-pen); } & code { font-size: 11.5px; } }

/* test text */
.adv-sieve .adv-sieve-textwrap { min-height: 0; display: grid; grid-template-rows: auto minmax(0, 1fr); }
.adv-sieve .adv-sieve-texthead { display: flex; align-items: center; gap: 10px; padding: 10px 16px 4px; font-size: 10.5px; font-weight: 750; letter-spacing: .1em; text-transform: uppercase; color: var(--adv-sieve-faint); & output { margin-left: auto; font: 500 11px var(--adv-sieve-mono); letter-spacing: 0; text-transform: none; } }
.adv-sieve .adv-sieve-mini { height: 22px; padding: 0 8px; border-radius: 6px; font-size: 11px; font-weight: 650; letter-spacing: 0; text-transform: none; color: var(--adv-sieve-mute); &:hover:not(:disabled) { background: var(--adv-sieve-hover); color: var(--adv-sieve-ink); } }
.adv-sieve .adv-sieve-text {
  position: relative; min-height: 0; margin: 0 10px 10px; border-radius: 10px; background: var(--adv-sieve-panel); box-shadow: inset 0 0 0 1px var(--adv-sieve-line);
  & textarea, & .mirror { position: absolute; inset: 0; width: 100%; height: 100%; margin: 0; padding: 12px 14px; border: 0; font: 13px/1.8 var(--adv-sieve-mono); white-space: pre-wrap; overflow-wrap: anywhere; word-break: normal; tab-size: 4; letter-spacing: 0; overflow-y: auto; scrollbar-gutter: stable; }
  & textarea { resize: none; background: transparent; color: transparent; caret-color: var(--adv-sieve-ink); outline: none; border-radius: 10px; scrollbar-width: thin; }
  & textarea::selection { background: color-mix(in oklch, var(--adv-sieve-ink) 16%, transparent); }
  & textarea:focus-visible { box-shadow: inset 0 0 0 1.5px var(--adv-sieve-ink); }
  & .mirror { overflow-y: hidden; pointer-events: none; color: var(--adv-sieve-ink); scrollbar-width: thin; }
  & mark { color: inherit; background: none; border-radius: 3px; box-shadow: 0 0 0 1px color-mix(in oklch, var(--adv-sieve-ink) 55%, transparent); box-decoration-break: clone; -webkit-box-decoration-break: clone;
    background-image: linear-gradient(var(--adv-sieve-accent), var(--adv-sieve-accent)); background-repeat: no-repeat; background-size: 100% 100%; }
  & mark.odd { background-image: linear-gradient(color-mix(in oklch, var(--adv-sieve-accent) 55%, var(--adv-sieve-panel)), color-mix(in oklch, var(--adv-sieve-accent) 55%, var(--adv-sieve-panel))); }
  & mark .grp { background: var(--g); border-radius: 2px; box-shadow: inset 0 -2px 0 color-mix(in oklch, var(--g) 60%, var(--adv-sieve-ink)); }
  & mark.is-hot { box-shadow: 0 0 0 2px var(--adv-sieve-ink); }
  & .zero { display: inline-block; width: 0; height: 1.3em; vertical-align: -.3em; box-shadow: 0 0 0 1px var(--adv-sieve-pen); }
  & .mirror.is-fresh mark { animation: adv-sieve-swipe .5s var(--adv-sieve-ease) backwards; animation-delay: calc(min(var(--i), 24) * 26ms); }
}
@keyframes adv-sieve-swipe { from { background-size: 0% 100%; box-shadow: 0 0 0 1px transparent; } }

/* side panel */
.adv-sieve .adv-sieve-side { grid-area: side; min-height: 0; display: grid; grid-template-rows: auto minmax(0, 1fr); border-left: 1px solid var(--adv-sieve-line); background: var(--adv-sieve-panel); }
.adv-sieve .adv-sieve-tabs {
  display: flex; padding: 0 8px; border-bottom: 1px solid var(--adv-sieve-line);
  & button { position: relative; height: 40px; padding: 0 9px; font-size: 12.5px; font-weight: 650; color: var(--adv-sieve-mute); white-space: nowrap; }
  & button::after { content: ""; position: absolute; left: 8px; right: 8px; bottom: -1px; height: 3px; border-radius: 3px 3px 0 0; background: var(--adv-sieve-ink); scale: 0 1; transition: scale .35s var(--adv-sieve-ease); }
  & button[aria-selected="true"] { color: var(--adv-sieve-ink); }
  & button[aria-selected="true"]::after { scale: 1 1; }
  & output { font: 600 10.5px var(--adv-sieve-mono); padding: 1px 5px; border-radius: 5px; background: var(--adv-sieve-hover); }
  & output.ok { background: color-mix(in oklab, var(--adv-sieve-ok) 18%, var(--adv-sieve-panel)); color: var(--adv-sieve-ok); }
  & output.bad { background: color-mix(in oklab, var(--adv-sieve-pen) 14%, var(--adv-sieve-panel)); color: var(--adv-sieve-pen); }
}
.adv-sieve .adv-sieve-panel { min-height: 0; overflow-y: auto; scrollbar-width: thin; scrollbar-color: var(--adv-sieve-line2) transparent; }
.adv-sieve .adv-sieve-none { padding: 18px 16px; font-size: 12.5px; color: var(--adv-sieve-faint); text-wrap: pretty; & b { display: block; margin-bottom: 4px; color: var(--adv-sieve-mute); font-size: 13px; } }
.adv-sieve .adv-sieve-ml { display: grid; }
.adv-sieve .adv-sieve-m {
  display: grid; gap: 4px; width: 100%; padding: 9px 14px; border-bottom: 1px solid var(--adv-sieve-line); text-align: left; transition: background .15s;
  &:hover, &.is-hot { background: color-mix(in oklch, var(--adv-sieve-accent) 22%, var(--adv-sieve-panel)); }
  &[aria-selected="true"] { background: color-mix(in oklch, var(--adv-sieve-accent) 38%, var(--adv-sieve-panel)); box-shadow: inset 3px 0 0 var(--adv-sieve-ink); }
  & .h { display: flex; gap: 8px; align-items: baseline; font: 600 10.5px var(--adv-sieve-mono); color: var(--adv-sieve-faint); }
  & .h b { color: var(--adv-sieve-ink); }
  & .txt { font: 12.5px var(--adv-sieve-mono); white-space: pre-wrap; word-break: break-all; }
  & dl { display: grid; grid-template-columns: auto minmax(0, 1fr); gap: 2px 8px; font: 11.5px var(--adv-sieve-mono); }
  & dt { padding: 0 5px; border-radius: 3px; background: var(--g, var(--adv-sieve-hover)); color: var(--adv-sieve-ink); font-weight: 650; align-self: start; }
  & dd { color: var(--adv-sieve-mute); white-space: pre-wrap; word-break: break-all; }
  & dd i { color: var(--adv-sieve-faint); }
  animation: adv-sieve-rise .3s var(--adv-sieve-ease) backwards; animation-delay: calc(min(var(--i), 16) * 22ms);
}
@keyframes adv-sieve-rise { from { opacity: 0; translate: 0 4px; } }
.adv-sieve .adv-sieve-ex {
  display: grid; padding: 10px 8px 14px;
  & li { display: grid; grid-template-columns: auto minmax(0, 1fr); gap: 10px; align-items: baseline; padding: 5px 8px 5px calc(8px + var(--d) * 14px); border-radius: 7px; cursor: default; transition: background .15s; animation: adv-sieve-rise .3s var(--adv-sieve-ease) backwards; animation-delay: calc(min(var(--i), 20) * 18ms); }
  & li:hover { background: color-mix(in oklch, var(--adv-sieve-accent) 30%, var(--adv-sieve-panel)); }
  & code { padding: 1px 6px; border-radius: 4px; font-size: 12px; font-weight: 650; background: var(--g, var(--adv-sieve-hover)); white-space: nowrap; }
  & span { font-size: 12px; color: var(--adv-sieve-mute); text-wrap: pretty; }
  & .ref { margin-top: 12px; padding: 10px 8px 4px; border-top: 1px solid var(--adv-sieve-line); display: grid; gap: 6px; animation: none; grid-template-columns: 1fr; }
  & .ref h4 { margin: 0; font-size: 10.5px; font-weight: 750; letter-spacing: .1em; text-transform: uppercase; color: var(--adv-sieve-faint); }
  & .ref div { display: flex; flex-wrap: wrap; gap: 4px; }
  & .ref button { height: 26px; padding: 0 8px; border-radius: 6px; font: 600 12px var(--adv-sieve-mono); box-shadow: inset 0 0 0 1px var(--adv-sieve-line2); transition: background .15s; }
  & .ref button:hover { background: var(--adv-sieve-accent); box-shadow: none; }
}
.adv-sieve .adv-sieve-rep {
  display: grid; gap: 10px; padding: 14px;
  & label { display: grid; gap: 6px; font-size: 10.5px; font-weight: 750; letter-spacing: .1em; text-transform: uppercase; color: var(--adv-sieve-faint); }
  & input { height: 34px; padding: 0 10px; border: 0; border-radius: 8px; background: var(--adv-sieve-bg); box-shadow: inset 0 0 0 1.5px var(--adv-sieve-line2); font: 13px var(--adv-sieve-mono); letter-spacing: 0; text-transform: none; color: var(--adv-sieve-ink); outline: none; }
  & input:focus { box-shadow: inset 0 0 0 2px var(--adv-sieve-ink); }
  & pre { margin: 0; padding: 12px; border-radius: 9px; background: var(--adv-sieve-bg); box-shadow: inset 0 0 0 1px var(--adv-sieve-line); font: 12px/1.75 var(--adv-sieve-mono); white-space: pre-wrap; word-break: break-word; max-height: 330px; overflow: auto; }
  & pre ins { text-decoration: none; background: color-mix(in oklch, var(--adv-sieve-g4) 80%, transparent); border-radius: 3px; box-decoration-break: clone; -webkit-box-decoration-break: clone; }
  & .row { display: flex; align-items: center; gap: 8px; font-size: 11.5px; color: var(--adv-sieve-faint); }
  & .row .adv-sieve-mini { margin-left: auto; box-shadow: inset 0 0 0 1px var(--adv-sieve-line2); height: 26px; }
  & .help { font-size: 11.5px; color: var(--adv-sieve-faint); text-wrap: pretty; } & .help code { color: var(--adv-sieve-ink); background: var(--adv-sieve-hover); padding: 0 3px; border-radius: 3px; }
}
.adv-sieve .adv-sieve-tests {
  display: grid; gap: 8px; padding: 12px;
  & .sum { display: flex; align-items: center; gap: 8px; font-size: 12px; color: var(--adv-sieve-mute); }
  & .sum b { font-size: 13px; color: var(--adv-sieve-ink); }
  & .bar { flex: 1; height: 6px; border-radius: 3px; background: color-mix(in oklab, var(--adv-sieve-pen) 25%, var(--adv-sieve-panel)); overflow: hidden; }
  & .bar i { display: block; height: 100%; width: 100%; background: var(--adv-sieve-ok); transform-origin: left; scale: var(--p) 1; transition: scale .5s var(--adv-sieve-spring); }
  & ul { display: grid; gap: 4px; }
  & li { display: grid; grid-template-columns: 20px minmax(0, 1fr) auto 24px; align-items: center; gap: 8px; padding: 6px 6px 6px 8px; border-radius: 8px; background: var(--adv-sieve-bg); box-shadow: inset 0 0 0 1px var(--adv-sieve-line); transition: box-shadow .25s, background .25s; @starting-style { opacity: 0; translate: 0 -4px; } }
  & li.fail { box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--adv-sieve-pen) 45%, transparent); background: color-mix(in oklab, var(--adv-sieve-pen) 6%, var(--adv-sieve-panel)); }
  & li > i { display: grid; place-items: center; width: 18px; height: 18px; border-radius: 50%; color: var(--adv-sieve-panel); background: var(--adv-sieve-ok); }
  & li.fail > i { background: var(--adv-sieve-pen); }
  & li > i svg { width: 11px; height: 11px; stroke-width: 2.4; }
  & li code { font-size: 12px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & .exp { height: 24px; padding: 0 8px; border-radius: 6px; font-size: 11px; font-weight: 700; white-space: nowrap; box-shadow: inset 0 0 0 1px var(--adv-sieve-line2); }
  & .exp:hover { background: var(--adv-sieve-hover); }
  & .rm { display: grid; place-items: center; width: 24px; height: 24px; border-radius: 6px; color: var(--adv-sieve-faint); }
  & .rm:hover { color: var(--adv-sieve-pen); background: var(--adv-sieve-hover); }
  & .rm svg { width: 13px; height: 13px; }
  & form { display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 6px; margin: 0; }
  & form input { height: 32px; padding: 0 10px; border: 0; border-radius: 8px; background: var(--adv-sieve-bg); box-shadow: inset 0 0 0 1.5px var(--adv-sieve-line2); font: 12px var(--adv-sieve-mono); outline: none; min-width: 0; }
  & form input:focus { box-shadow: inset 0 0 0 2px var(--adv-sieve-ink); }
  & form button { height: 32px; padding: 0 12px; border-radius: 8px; background: var(--adv-sieve-ink); color: var(--adv-sieve-accent); font-size: 12px; font-weight: 700; }
}

/* foot, toast */
.adv-sieve .adv-sieve-foot {
  grid-area: foot; display: flex; align-items: center; gap: 16px; height: 30px; padding: 0 16px; border-top: 1px solid var(--adv-sieve-line); font-size: 11px; color: var(--adv-sieve-faint); white-space: nowrap; overflow: hidden;
  & span { display: inline-flex; align-items: center; gap: 3px; } & kbd:last-of-type { margin-right: 3px; }
  & output { margin-left: auto; font: 11px var(--adv-sieve-mono); }
  & output.slow { color: var(--adv-sieve-pen); font-weight: 700; }
}
.adv-sieve .adv-sieve-toast {
  position: absolute; z-index: 40; left: 50%; bottom: 42px; translate: -50% 12px; opacity: 0; pointer-events: none; display: flex; align-items: center; gap: 12px; padding: 9px 10px 9px 14px; border-radius: 10px;
  background: var(--adv-sieve-ink); color: var(--adv-sieve-panel); font-size: 12.5px; font-weight: 560; white-space: nowrap; box-shadow: 0 14px 30px -12px oklch(0.2 0.01 70 / .5);
  transition: opacity .25s, translate .45s var(--adv-sieve-spring);
  &.is-on { opacity: 1; translate: -50% 0; pointer-events: auto; }
  & button { height: 24px; padding: 0 9px; border-radius: 6px; font-weight: 700; color: var(--adv-sieve-ink); background: var(--adv-sieve-accent); }
}

/* responsive */
@container adv-sieve (width < 1080px) {
  .adv-sieve .adv-sieve-app { grid-template-columns: 172px minmax(0, 1fr) 286px; }
  .adv-sieve .adv-sieve-lib .adv-sieve-tip { display: none; }
}
@container adv-sieve (width < 900px) {
  .adv-sieve .adv-sieve-app { grid-template-columns: minmax(0, 1fr); grid-template-areas: "top" "mnav" "work" "foot"; }
  .adv-sieve .adv-sieve-lib { display: none; grid-area: work; border-right: 0; }
  .adv-sieve .adv-sieve-side { display: none; border-left: 0; grid-area: work; }
  .adv-sieve .adv-sieve-mnav { display: grid; grid-template-columns: repeat(3, 1fr); gap: 4px; padding: 6px 10px; border-bottom: 1px solid var(--adv-sieve-line);
    & button { height: 30px; border-radius: 7px; font-size: 12.5px; font-weight: 650; color: var(--adv-sieve-mute); }
    & button[aria-selected="true"] { background: var(--adv-sieve-ink); color: var(--adv-sieve-accent); } }
  .adv-sieve[data-view="library"] .adv-sieve-lib { display: flex; }
  .adv-sieve[data-view="results"] .adv-sieve-side { display: grid; }
  .adv-sieve:not([data-view="editor"]) .adv-sieve-work { display: none; }
  .adv-sieve .adv-sieve-foot span:nth-child(n+3) { display: none; }
}
@container adv-sieve (width < 600px) {
  .adv-sieve .adv-sieve-pat { flex-wrap: wrap; height: auto; padding: 0 6px 6px 12px; }
  .adv-sieve .adv-sieve-pat .field { flex: 1 1 calc(100% - 40px); height: 44px; }
  .adv-sieve .adv-sieve-flags { margin-left: auto; }
  .adv-sieve .adv-sieve-patrow { padding: 10px 10px 6px; }
  .adv-sieve .adv-sieve-foot span:nth-child(n+2) { display: none; }
}
@container adv-sieve (width < 420px) {
  .adv-sieve .adv-sieve-brand small { display: none; }
  .adv-sieve .adv-sieve-tabs button { padding: 0 7px; font-size: 12px; }
  .adv-sieve .adv-sieve-flags button { width: 24px; }
}

@media (prefers-reduced-motion: reduce) {
  .adv-sieve *, .adv-sieve *::before, .adv-sieve *::after { animation-duration: .01ms !important; animation-delay: 0s !important; transition-duration: .01ms !important; }
}

