@property --adv-tock-runs { syntax: "<integer>"; inherits: false; initial-value: 0; }
.adv-tock {
  /* re-theme with these four */
  --adv-tock-bg: oklch(0.955 0.008 70);
  --adv-tock-panel: oklch(0.987 0.004 70);
  --adv-tock-ink: oklch(0.24 0.016 50);
  --adv-tock-accent: oklch(0.62 0.19 33);
  /* derived */
  --adv-tock-line: color-mix(in oklch, var(--adv-tock-ink) 11%, transparent);
  --adv-tock-line2: color-mix(in oklch, var(--adv-tock-ink) 19%, transparent);
  --adv-tock-hover: color-mix(in oklch, var(--adv-tock-ink) 5%, transparent);
  --adv-tock-mute: color-mix(in oklch, var(--adv-tock-ink) 68%, var(--adv-tock-bg));
  --adv-tock-faint: color-mix(in oklch, var(--adv-tock-ink) 45%, var(--adv-tock-bg));
  --adv-tock-tint: color-mix(in oklab, var(--adv-tock-accent) 10%, var(--adv-tock-panel));
  --adv-tock-tint2: color-mix(in oklab, var(--adv-tock-accent) 20%, var(--adv-tock-panel));
  --adv-tock-err: oklch(0.5 0.17 25);
  --adv-tock-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  --adv-tock-ease: cubic-bezier(.2, .8, .2, 1);
  --adv-tock-spring: linear(0, 0.12 5%, 0.42 11%, 0.77 18%, 0.97 25%, 1.05 31%, 1.06 37%, 1.03 45%, 1.005 56%, 0.998 70%, 1);

  position: relative; width: 100%; height: var(--adv-tock-h, 680px); box-sizing: border-box; overflow: clip; isolation: isolate;
  container-type: inline-size; container-name: adv-tock;
  border-radius: 14px; background: var(--adv-tock-bg); color: var(--adv-tock-ink); color-scheme: light; accent-color: var(--adv-tock-accent);
  font: 13px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif; box-shadow: inset 0 0 0 1px var(--adv-tock-line);

  & *, & *::before, & *::after { box-sizing: border-box; }
  & :focus-visible { outline: 2px solid var(--adv-tock-accent); outline-offset: 2px; }
  & button, & input, & select { font: inherit; color: inherit; }
  & button { cursor: pointer; background: none; border: 0; padding: 0; }
  & button:disabled { cursor: not-allowed; opacity: .4; }
  & h3, & p, & ol, & ul { margin: 0; padding: 0; }
  & ol, & ul { list-style: none; }
  & [hidden] { display: none !important; }
  & svg { width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; flex: none; }
  & kbd { display: inline-grid; place-items: center; min-width: 17px; height: 17px; padding: 0 4px; border-radius: 4px; font: 600 10px/1 var(--adv-tock-mono); color: var(--adv-tock-mute); background: var(--adv-tock-panel); box-shadow: inset 0 0 0 1px var(--adv-tock-line2), 0 1px 0 var(--adv-tock-line); }
  & output { font-variant-numeric: tabular-nums; }
  & select { height: 30px; padding: 0 26px 0 9px; border: 0; border-radius: 8px; appearance: none; cursor: pointer; background-color: var(--adv-tock-panel); background-image: linear-gradient(45deg, transparent 50%, var(--adv-tock-faint) 50%), linear-gradient(135deg, var(--adv-tock-faint) 50%, transparent 50%); background-position: calc(100% - 14px) 55%, calc(100% - 10px) 55%; background-size: 4px 4px; background-repeat: no-repeat; box-shadow: inset 0 0 0 1px var(--adv-tock-line2); font-size: 12.5px; outline: none; }
  & select:focus-visible { box-shadow: inset 0 0 0 1.5px var(--adv-tock-accent); }
}
.adv-tock .adv-tock-app {
  height: 100%; display: grid; grid-template-columns: 224px minmax(0, 1fr) 312px; grid-template-rows: auto auto minmax(0, 1fr) auto;
  grid-template-areas: "top top top" "mnav mnav mnav" "jobs main side" "foot foot foot";
}
.adv-tock .adv-tock-top { grid-area: top; display: flex; align-items: center; gap: 12px; padding: 10px 14px 10px 16px; border-bottom: 1px solid var(--adv-tock-line); background: var(--adv-tock-panel); }
.adv-tock .adv-tock-brand {
