@media (prefers-reduced-motion: reduce) {
  .adv-tock *, .adv-tock *::before, .adv-tock *::after { animation-duration: .01ms !important; animation-delay: 0s !important; transition-duration: .01ms !important; transition-delay: 0s !important; }
}

