/* ── Tock · cron builder ─────────────────────────────────────────────
   Each of the five fields parses to a set of values (names, ranges, steps
   and lists, 7 as Sunday); the pickers edit that set and write back the
   shortest equivalent syntax. Next runs walk forward through wall-clock
   time in the chosen IANA zone using Intl formatToParts, skipping whole
   days and hours that cannot match, and day-of-month OR day-of-week apply
   exactly as cron does when both are restricted. */
const $ = (s, el = root) => el.querySelector(s);
const $$ = (s, el = root) => [...el.querySelectorAll(s)];
const RM = matchMedia('(prefers-reduced-motion: reduce)');
const esc = s => String(s == null ? '' : s).replace(/[&<>"']/g, c => '&#' + c.charCodeAt(0) + ';');
const isMac = /Mac|iPhone|iPad/.test(navigator.platform || navigator.userAgent || '');
const pad = n => String(n).padStart(2, '0');
const MONTHS = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'];
const DAYS = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];
const F = [
  { key: 'minute', label: 'minute', short: 'min', min: 0, max: 59, cols: 10, steps: [2, 5, 10, 15, 20, 30], def: { step: '*/15', range: '0-29', list: '0' } },
  { key: 'hour', label: 'hour', short: 'hour', min: 0, max: 23, cols: 8, steps: [2, 3, 4, 6, 8, 12], def: { step: '*/6', range: '9-17', list: '9' } },
  { key: 'dom', label: 'day of month', short: 'day', min: 1, max: 31, cols: 7, steps: [2, 5, 7, 10, 15], def: { step: '*/7', range: '1-7', list: '1' } },
  { key: 'month', label: 'month', short: 'mon', min: 1, max: 12, cols: 6, steps: [2, 3, 4, 6], names: ['JAN', 'FEB', 'MAR', 'APR', 'MAY', 'JUN', 'JUL', 'AUG', 'SEP', 'OCT', 'NOV', 'DEC'], def: { step: '*/3', range: '3-9', list: '1' } },
  { key: 'dow', label: 'day of week', short: 'wkday', min: 0, max: 6, cols: 7, steps: [2, 3], names: ['SUN', 'MON', 'TUE', 'WED', 'THU', 'FRI', 'SAT'], def: { step: '*/2', range: '1-5', list: '1' } },
];
const MACROS = { '@yearly': '0 0 1 1 *', '@annually': '0 0 1 1 *', '@monthly': '0 0 1 * *', '@weekly': '0 0 * * 0', '@daily': '0 0 * * *', '@midnight': '0 0 * * *', '@hourly': '0 * * * *' };
const TZS = ['UTC', 'Europe/Berlin', 'Europe/London', 'America/Chicago', 'America/New_York', 'America/Sao_Paulo', 'Asia/Tokyo', 'Australia/Sydney'];
const PRESETS = [['Every 15 min', '*/15 * * * *'], ['Hourly', '0 * * * *'], ['Weekdays 09:30', '30 9 * * 1-5'], ['Nightly 02:00', '0 2 * * *'], ['Sundays 18:00', '0 18 * * 0'], ['1st of the month', '0 6 1 * *'], ['Quarterly', '0 7 1 1,4,7,10 *']];
const JOBS = [
  { name: 'warehouse-stock-sync', expr: '*/15 6-22 * * *', tz: 'Europe/Berlin', on: true, desc: 'Pull stock levels from the Leipzig warehouse' },
  { name: 'abandoned-cart-email', expr: '30 9 * * 1-5', tz: 'Europe/Berlin', on: true, desc: 'Remind shoppers about carts left overnight' },
  { name: 'db-backup', expr: '0 2 * * *', tz: 'UTC', on: true, desc: 'Snapshot the orders database to cold storage' },
  { name: 'invoice-reminders', expr: '0 6 1,15 * *', tz: 'Europe/London', on: true, desc: 'Email trade customers with open invoices' },
  { name: 'quarterly-tax-export', expr: '0 7 1 1,4,7,10 *', tz: 'Europe/Berlin', on: true, desc: 'Export VAT totals for the accountant' },
  { name: 'plant-care-tips', expr: '0 18 * 3-9 0', tz: 'Europe/Berlin', on: false, desc: 'Sunday newsletter, growing season only' },
];

/* ── parse / serialise / describe ── */
function parseField(str, f) {
  const s = String(str).trim().toUpperCase();
  if (!s) throw 'is empty';
  const set = new Set();
  const val = (tok, wrap) => {
    if (f.names) { const i = f.names.indexOf(tok); if (i >= 0) return i + f.min; }
    if (!/^\d+$/.test(tok)) throw '“' + tok.toLowerCase() + '” is not a value';
    const n = +tok;
    if (f.key === 'dow' && n === 7) return wrap ? 0 : 7;
    if (n < f.min || n > f.max) throw n + ' is outside ' + f.min + '–' + f.max;
    return n;
  };
  for (const part of s.split(',')) {
    if (!part) throw 'has an empty list item';
    const bits = part.split('/'); if (bits.length > 2) throw 'has two steps in “' + part + '”';
    let st = 1;
    if (bits[1] != null) { if (!/^\d+$/.test(bits[1]) || +bits[1] < 1) throw 'step “' + bits[1] + '” must be 1 or more'; st = +bits[1]; }
    let a, b; const r = bits[0];
    if (r === '*') { a = f.min; b = f.max; }
    else if (r.includes('-')) { const [x, y] = r.split('-'); a = val(x, true); b = val(y, false); if (a > b) throw 'range ' + x + '-' + y + ' runs backwards'; }
    else { a = val(r, true); b = bits[1] != null ? f.max : a; }
    for (let v = a; v <= b; v += st) set.add(f.key === 'dow' ? v % 7 : v);
  }
  return { set, star: s === '*' || s === '*/1', raw: String(str).trim() };
}
function parseExpr(expr) {
  let e = String(expr).trim();
  if (MACROS[e.toLowerCase()]) e = MACROS[e.toLowerCase()];
  const parts = e.split(/\s+/).filter(Boolean);
  if (parts.length !== 5) return { error: 'Expected 5 fields (minute hour day month weekday), found ' + parts.length + '.', field: -1, parts };
  const P = [];
  for (let i = 0; i < 5; i++) { try { P.push(parseField(parts[i], F[i])); } catch (m) { return { error: 'The ' + F[i].label + ' field ' + m + '.', field: i, parts }; } }
  return { P, parts };
