  --adv-ballast-panel: oklch(0.205 0.011 150);
  --adv-ballast-ink: oklch(0.93 0.012 105);
  --adv-ballast-accent: oklch(0.88 0.165 102);
  /* derived */
  --adv-ballast-line: color-mix(in oklch, var(--adv-ballast-ink) 9%, transparent);
  --adv-ballast-line2: color-mix(in oklch, var(--adv-ballast-ink) 16%, transparent);
  --adv-ballast-hover: color-mix(in oklch, var(--adv-ballast-ink) 6%, transparent);
  --adv-ballast-sunk: color-mix(in oklch, var(--adv-ballast-bg) 75%, black);
  --adv-ballast-mute: color-mix(in oklch, var(--adv-ballast-ink) 66%, var(--adv-ballast-bg));
  --adv-ballast-faint: color-mix(in oklch, var(--adv-ballast-ink) 40%, var(--adv-ballast-bg));
  --adv-ballast-tint: color-mix(in oklch, var(--adv-ballast-accent) 14%, transparent);
  --adv-ballast-on: oklch(0.22 0.04 100);
