  --adv-ballast-zoom: cubic-bezier(.65, 0, .2, 1);
  --adv-ballast-spring: linear(0, 0.12 5%, 0.42 11%, 0.77 18%, 0.97 25%, 1.05 31%, 1.06 37%, 1.03 45%, 1.005 56%, 0.998 70%, 1);

  position: relative; width: 100%; height: var(--adv-ballast-h, 680px); box-sizing: border-box; overflow: clip; isolation: isolate;
  container-type: inline-size; container-name: adv-ballast;
  border-radius: 14px; background: var(--adv-ballast-bg); color: var(--adv-ballast-ink); color-scheme: dark; accent-color: var(--adv-ballast-accent);
  font: 13px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif; -webkit-font-smoothing: antialiased;

  & *, & *::before, & *::after { box-sizing: border-box; }
  & :focus-visible { outline: 2px solid var(--adv-ballast-accent); outline-offset: 1px; }
