}
.adv-ballast .adv-ballast-search {
  display: flex; align-items: center; gap: 7px; width: clamp(150px, 22cqi, 240px); height: 32px; padding: 0 10px; border-radius: 9px; background: var(--adv-ballast-sunk); box-shadow: inset 0 0 0 1px var(--adv-ballast-line2); cursor: text; transition: box-shadow .2s;
