  & .tag { padding: 0 5px; border-radius: 4px; font: 700 9.5px system-ui; letter-spacing: .05em; text-transform: uppercase; color: var(--adv-ballast-faint); box-shadow: inset 0 0 0 1px var(--adv-ballast-line2); }
