  & output { margin-left: auto; font: 11px var(--adv-ballast-mono); color: var(--adv-ballast-mute); white-space: nowrap; }
  & .b { height: 4px; border-radius: 2px; background: var(--adv-ballast-line); overflow: hidden; }
  & .b i { display: block; height: 100%; background: var(--c); transform-origin: left; scale: var(--p) 1; transition: scale .6s var(--adv-ballast-ease); border-radius: 2px; }
