  display: grid; gap: 6px;
  & button { display: grid; gap: 3px; width: 100%; padding: 9px 10px; border-radius: 10px; text-align: left; background: color-mix(in oklch, var(--adv-ballast-warn) 9%, transparent); box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--adv-ballast-warn) 28%, transparent); transition: background .2s; }
