  & button:hover { background: var(--adv-ballast-hover); color: var(--adv-ballast-ink); }
  & .sep { color: var(--adv-ballast-faint); }
  & [aria-current] { padding: 4px 7px; color: var(--adv-ballast-ink); font-weight: 700; overflow: hidden; text-overflow: ellipsis; }
  & .sz { margin-left: auto; padding-left: 12px; color: var(--adv-ballast-faint); }
  & .sz b { color: var(--adv-ballast-accent); font-weight: 700; }
}
.adv-ballast .adv-ballast-stage { position: relative; min-height: 0; border-radius: 12px; overflow: hidden; background: var(--adv-ballast-sunk); box-shadow: inset 0 0 0 1px var(--adv-ballast-line); }
.adv-ballast .adv-ballast-map { position: absolute; inset: 0; transform-origin: 0 0; }
.adv-ballast .adv-ballast-tile {
  position: absolute; left: var(--x); top: var(--y); width: var(--w); height: var(--h); padding: 0; overflow: hidden; border-radius: 6px; text-align: left;
  background: oklch(0.36 0.065 var(--hue)); box-shadow: inset 0 0 0 1px oklch(0.48 0.075 var(--hue) / .6);
  transition: background .2s, box-shadow .2s, opacity .3s, filter .3s;
  & .inner { position: absolute; inset: 0; pointer-events: none; }
  & .inner i { position: absolute; left: var(--x); top: var(--y); width: var(--w); height: var(--h); border-radius: 3px; background: oklch(0.42 0.07 var(--hue) / .55); }
  & .lab { position: absolute; left: 0; top: 0; right: 0; display: grid; gap: 1px; padding: 6px 8px; pointer-events: none; text-shadow: 0 1px 2px oklch(0 0 0 / .45); }
  & .lab b { font: 650 12px/1.2 system-ui; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & .lab small { font: 10.5px var(--adv-ballast-mono); color: color-mix(in oklch, var(--adv-ballast-ink) 75%, transparent); white-space: nowrap; }
  & .lab .dir { color: oklch(0.85 0.08 var(--hue)); }
  &.is-file { background: oklch(0.32 0.05 var(--hue)); }
  &.is-tiny .lab { display: none; }
  &.is-small .lab small { display: none; }
  &:hover { background: oklch(0.43 0.08 var(--hue)); box-shadow: inset 0 0 0 1.5px oklch(0.7 0.1 var(--hue)); z-index: 1; }
  &[aria-pressed="true"] { box-shadow: inset 0 0 0 2px var(--adv-ballast-accent); z-index: 2; }
  &:focus-visible { outline: none; box-shadow: inset 0 0 0 2px var(--adv-ballast-ink), 0 0 0 2px var(--adv-ballast-accent); z-index: 3; }
  &.is-dup::after { content: ""; position: absolute; right: 6px; top: 6px; width: 8px; height: 8px; border-radius: 50%; background: var(--adv-ballast-warn); box-shadow: 0 0 0 3px color-mix(in oklch, var(--adv-ballast-warn) 30%, transparent); }
}
.adv-ballast .adv-ballast-map.is-searching .adv-ballast-tile:not(.is-hit) { opacity: .28; filter: saturate(.3); }
.adv-ballast .adv-ballast-map.is-searching .adv-ballast-tile.is-hit { box-shadow: inset 0 0 0 2px var(--adv-ballast-accent); }
.adv-ballast .adv-ballast-empty { position: absolute; inset: 0; display: grid; place-items: center; align-content: center; gap: 6px; padding: 20px; text-align: center; color: var(--adv-ballast-faint); font-size: 12.5px; & b { color: var(--adv-ballast-mute); font-size: 14px; } }

/* info */
.adv-ballast .adv-ballast-info { grid-area: info; min-height: 0; overflow-y: auto; scrollbar-width: thin; padding: 16px 14px; display: grid; align-content: start; gap: 14px; border-left: 1px solid var(--adv-ballast-line); background: var(--adv-ballast-panel); }
.adv-ballast .adv-ballast-ihead {
  display: grid; gap: 4px;
  & small { font: 11px var(--adv-ballast-mono); color: var(--adv-ballast-faint); word-break: break-all; }
  & h2 { margin: 0; font-size: clamp(16px, 1.6cqi, 19px); font-weight: 760; letter-spacing: -.02em; line-height: 1.2; word-break: break-word; text-wrap: balance; }
  & .kind { justify-self: start; padding: 1px 7px; border-radius: 5px; font: 700 10px system-ui; letter-spacing: .06em; text-transform: uppercase; background: oklch(0.36 0.065 var(--hue, 100)); }
