  & output { text-align: right; font: 600 12px var(--adv-ballast-mono); }
  & i { height: 6px; border-radius: 3px; background: var(--adv-ballast-line); overflow: hidden; }
  & i::before { content: ""; display: block; height: 100%; width: 100%; background: var(--adv-ballast-accent); transform-origin: left; scale: var(--p) 1; transition: scale .55s var(--adv-ballast-ease); border-radius: 3px; }
  & div.on span { color: var(--adv-ballast-accent); font-weight: 700; }
}
.adv-ballast .adv-ballast-share { font-size: 12px; color: var(--adv-ballast-mute); text-wrap: pretty; & b { color: var(--adv-ballast-ink); font-variant-numeric: tabular-nums; } }
.adv-ballast .adv-ballast-top5 {
  display: grid; gap: 2px;
  & button { display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 8px; align-items: center; width: 100%; padding: 6px 8px; border-radius: 7px; text-align: left; font: 12px var(--adv-ballast-mono); transition: background .15s; }
  & button:hover { background: var(--adv-ballast-hover); }
  & button span { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; display: flex; align-items: center; gap: 7px; }
  & button span i { width: 8px; height: 8px; border-radius: 2px; flex: none; background: oklch(0.6 0.1 var(--hue)); }
  & button output { color: var(--adv-ballast-mute); font-size: 11.5px; }
}
.adv-ballast .adv-ballast-warnbox { padding: 10px 12px; border-radius: 10px; font-size: 12px; color: var(--adv-ballast-ink); background: color-mix(in oklch, var(--adv-ballast-warn) 12%, transparent); box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--adv-ballast-warn) 35%, transparent); text-wrap: pretty; & code { font: 11.5px var(--adv-ballast-mono); } }
