.adv-ballast .adv-ballast-btn {
  display: inline-flex; align-items: center; gap: 6px; height: 30px; padding: 0 11px; border-radius: 8px; font-size: 12px; font-weight: 640; color: var(--adv-ballast-mute); box-shadow: inset 0 0 0 1px var(--adv-ballast-line2); transition: color .2s, box-shadow .2s, background .2s;
  & svg { width: 14px; height: 14px; }
  &:hover:not(:disabled) { color: var(--adv-ballast-ink); box-shadow: inset 0 0 0 1px var(--adv-ballast-faint); }
  &.pri { background: var(--adv-ballast-accent); color: var(--adv-ballast-on); box-shadow: none; }
}

/* foot, toast */
.adv-ballast .adv-ballast-foot {
  grid-area: foot; display: flex; align-items: center; gap: 16px; height: 30px; padding: 0 16px; border-top: 1px solid var(--adv-ballast-line); font-size: 11px; color: var(--adv-ballast-faint); white-space: nowrap; overflow: hidden;
  & span { display: inline-flex; align-items: center; gap: 3px; } & kbd:last-of-type { margin-right: 3px; }
  & output { margin-left: auto; font: 11px var(--adv-ballast-mono); }
}
.adv-ballast .adv-ballast-toast {
  position: absolute; z-index: 40; left: 50%; bottom: 42px; translate: -50% 12px; opacity: 0; pointer-events: none; padding: 9px 14px; border-radius: 10px; background: var(--adv-ballast-ink); color: var(--adv-ballast-bg); font-size: 12.5px; font-weight: 560; white-space: nowrap;
  box-shadow: 0 16px 34px -12px oklch(0 0 0 / .7); transition: opacity .25s, translate .45s var(--adv-ballast-spring);
