}

/* responsive */
@container adv-ballast (width < 1080px) {
  .adv-ballast .adv-ballast-app { grid-template-columns: 210px minmax(0, 1fr) 240px; }
}
@container adv-ballast (width < 900px) {
  .adv-ballast .adv-ballast-app { grid-template-columns: minmax(0, 1fr); grid-template-areas: "top" "mnav" "main" "foot"; }
  .adv-ballast .adv-ballast-mnav { display: grid; grid-template-columns: repeat(3, 1fr); gap: 4px; padding: 6px 10px; border-bottom: 1px solid var(--adv-ballast-line);
    & button { height: 30px; border-radius: 7px; font-size: 12.5px; font-weight: 640; color: var(--adv-ballast-mute); }
    & button[aria-selected="true"] { background: var(--adv-ballast-tint); color: var(--adv-ballast-ink); } }
  .adv-ballast .adv-ballast-side, .adv-ballast .adv-ballast-info { display: none; grid-area: main; border: 0; }
  .adv-ballast[data-view="chunks"] .adv-ballast-side { display: grid; }
  .adv-ballast[data-view="info"] .adv-ballast-info { display: grid; }
  .adv-ballast:not([data-view="map"]) .adv-ballast-main { display: none; }
  .adv-ballast .adv-ballast-foot span:nth-child(n+3) { display: none; }
}
@container adv-ballast (width < 560px) {
  .adv-ballast .adv-ballast-top { flex-wrap: wrap; }
  .adv-ballast .adv-ballast-search { order: 3; width: 100%; }
  .adv-ballast .adv-ballast-brand small { display: none; }
  .adv-ballast .adv-ballast-crumbs .sz { display: none; }
  .adv-ballast .adv-ballast-foot span:nth-child(n+2) { display: none; }
