@property --adv-cellar-left { syntax: "<angle>"; inherits: false; initial-value: 360deg; }
.adv-cellar {
  /* re-theme with these four */
  --adv-cellar-bg: oklch(0.19 0.02 330);
  --adv-cellar-panel: oklch(0.225 0.022 330);
  --adv-cellar-ink: oklch(0.94 0.012 340);
  --adv-cellar-accent: oklch(0.82 0.1 55);
  /* derived */
  --adv-cellar-line: color-mix(in oklch, var(--adv-cellar-ink) 9%, transparent);
  --adv-cellar-line2: color-mix(in oklch, var(--adv-cellar-ink) 16%, transparent);
  --adv-cellar-hover: color-mix(in oklch, var(--adv-cellar-ink) 5.5%, transparent);
  --adv-cellar-sunk: color-mix(in oklch, var(--adv-cellar-bg) 78%, black);
  --adv-cellar-mute: color-mix(in oklch, var(--adv-cellar-ink) 66%, var(--adv-cellar-bg));
  --adv-cellar-faint: color-mix(in oklch, var(--adv-cellar-ink) 40%, var(--adv-cellar-bg));
  --adv-cellar-tint: color-mix(in oklch, var(--adv-cellar-accent) 14%, transparent);
  --adv-cellar-on: oklch(0.24 0.04 50);
  --adv-cellar-dev: oklch(0.76 0.12 160);
  --adv-cellar-pre: oklch(0.82 0.12 95);
  --adv-cellar-prd: oklch(0.7 0.16 22);
  --adv-cellar-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  --adv-cellar-ease: cubic-bezier(.2, .8, .2, 1);
  --adv-cellar-spring: linear(0, 0.12 5%, 0.42 11%, 0.77 18%, 0.97 25%, 1.05 31%, 1.06 37%, 1.03 45%, 1.005 56%, 0.998 70%, 1);

  position: relative; width: 100%; height: var(--adv-cellar-h, 680px); box-sizing: border-box; overflow: clip; isolation: isolate;
  container-type: inline-size; container-name: adv-cellar;
  border-radius: 14px; background: var(--adv-cellar-bg); color: var(--adv-cellar-ink); color-scheme: dark; accent-color: var(--adv-cellar-accent);
  font: 13px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif; -webkit-font-smoothing: antialiased;

  & *, & *::before, & *::after { box-sizing: border-box; }
  & :focus-visible { outline: 2px solid var(--adv-cellar-accent); outline-offset: 1px; }
  & button, & input, & textarea, & select { font: inherit; color: inherit; }
  & button { cursor: pointer; background: none; border: 0; padding: 0; }
  & button:disabled { cursor: not-allowed; opacity: .4; }
  & h2, & h3, & p, & ol, & ul, & dl, & dd { margin: 0; padding: 0; }
  & ol, & ul { list-style: none; }
  & [hidden] { display: none !important; }
  & svg { width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; flex: none; }
  & kbd { display: inline-grid; place-items: center; min-width: 17px; height: 17px; padding: 0 4px; border-radius: 4px; font: 600 10px/1 var(--adv-cellar-mono); color: var(--adv-cellar-mute); box-shadow: inset 0 0 0 1px var(--adv-cellar-line2); }
  & output { font-variant-numeric: tabular-nums; }
  & h3 { font-size: 10.5px; font-weight: 750; letter-spacing: .1em; text-transform: uppercase; color: var(--adv-cellar-faint); }
  & .e-development { --c: var(--adv-cellar-dev); } & .e-preview { --c: var(--adv-cellar-pre); } & .e-production { --c: var(--adv-cellar-prd); }
}
.adv-cellar .adv-cellar-app {
  height: 100%; display: grid; grid-template-columns: minmax(0, 1fr) 300px; grid-template-rows: auto auto auto minmax(0, 1fr) auto;
  grid-template-areas: "top top" "bar bar" "mnav mnav" "main insp" "foot foot";
}
.adv-cellar .adv-cellar-top { grid-area: top; display: flex; align-items: center; gap: 10px; padding: 10px 14px 10px 16px; border-bottom: 1px solid var(--adv-cellar-line); }
.adv-cellar .adv-cellar-brand {
  display: flex; align-items: center; gap: 10px; margin-right: auto; min-width: 0;
  & svg { width: 24px; height: 24px; color: var(--adv-cellar-accent); }
  & span { display: grid; line-height: 1.15; min-width: 0; }
  & b { font-size: 15px; font-weight: 780; letter-spacing: -.02em; }
  & small { font-size: 11px; color: var(--adv-cellar-faint); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
}
.adv-cellar .adv-cellar-search {
  display: flex; align-items: center; gap: 7px; width: clamp(160px, 22cqi, 250px); height: 32px; padding: 0 6px 0 10px; border-radius: 9px; background: var(--adv-cellar-sunk); box-shadow: inset 0 0 0 1px var(--adv-cellar-line2); cursor: text; transition: box-shadow .2s;
  & svg { color: var(--adv-cellar-faint); }
  & input { flex: 1; min-width: 0; height: 100%; border: 0; outline: none; background: none; font-size: 12.5px; }
  & input::-webkit-search-cancel-button { display: none; }
  &:focus-within { box-shadow: inset 0 0 0 1.5px var(--adv-cellar-accent); }
}
.adv-cellar .adv-cellar-btn {
  display: inline-flex; align-items: center; gap: 6px; height: 32px; padding: 0 12px; border-radius: 9px; font-size: 12.5px; font-weight: 640; color: var(--adv-cellar-mute); white-space: nowrap; box-shadow: inset 0 0 0 1px var(--adv-cellar-line2); transition: color .2s, box-shadow .2s, background .2s, filter .2s;
  & svg { width: 15px; height: 15px; }
  &:hover:not(:disabled), &[aria-expanded="true"] { color: var(--adv-cellar-ink); box-shadow: inset 0 0 0 1px var(--adv-cellar-faint); }
  &.pri { background: var(--adv-cellar-accent); color: var(--adv-cellar-on); box-shadow: none; }
  &.pri:hover:not(:disabled) { filter: brightness(1.06); color: var(--adv-cellar-on); box-shadow: none; }
  &.sm { height: 28px; padding: 0 10px; font-size: 12px; }
  &.danger:hover:not(:disabled) { color: var(--adv-cellar-prd); box-shadow: inset 0 0 0 1px var(--adv-cellar-prd); }
}
.adv-cellar .adv-cellar-bar { grid-area: bar; display: flex; align-items: center; gap: 10px; padding: 10px 16px; border-bottom: 1px solid var(--adv-cellar-line); min-width: 0; }
.adv-cellar .adv-cellar-chips {
  display: flex; flex-wrap: wrap; gap: 4px;
  & button { display: inline-flex; align-items: center; gap: 5px; height: 26px; padding: 0 10px; border-radius: 99px; font-size: 12px; font-weight: 620; color: var(--adv-cellar-mute); box-shadow: inset 0 0 0 1px var(--adv-cellar-line2); transition: background .2s, color .2s; }
  & button[aria-checked="true"] { background: var(--adv-cellar-ink); color: var(--adv-cellar-bg); box-shadow: none; }
  & output { font-size: 11px; opacity: .7; }
}
.adv-cellar .adv-cellar-envpick { display: none; }
.adv-cellar .adv-cellar-count { margin-left: auto; font: 11.5px var(--adv-cellar-mono); color: var(--adv-cellar-faint); white-space: nowrap; }
.adv-cellar .adv-cellar-mnav { grid-area: mnav; display: none; }

/* matrix */
.adv-cellar .adv-cellar-main { grid-area: main; min-width: 0; min-height: 0; display: grid; grid-template-rows: minmax(0, 1fr) auto; }
.adv-cellar .adv-cellar-scroll { min-height: 0; overflow: auto; scrollbar-width: thin; scrollbar-color: var(--adv-cellar-line2) transparent; }
.adv-cellar .adv-cellar-grid { display: grid; grid-template-columns: minmax(190px, 1.15fr) repeat(3, minmax(150px, 1fr)); min-width: 680px; padding-bottom: 12px; }
.adv-cellar .adv-cellar-row {
  display: grid; grid-column: 1 / -1; grid-template-columns: subgrid; border-bottom: 1px solid var(--adv-cellar-line); transition: background .2s;
  &:hover { background: color-mix(in oklch, var(--adv-cellar-ink) 2.5%, transparent); }
  &[aria-selected="true"] { background: var(--adv-cellar-tint); }
  animation: adv-cellar-rise .35s var(--adv-cellar-ease) backwards; animation-delay: calc(min(var(--i), 20) * 18ms);
}
@keyframes adv-cellar-rise { from { opacity: 0; translate: 0 4px; } }
.adv-cellar .adv-cellar-head {
  position: sticky; top: 0; z-index: 3; display: grid; grid-column: 1 / -1; grid-template-columns: subgrid; background: var(--adv-cellar-bg); border-bottom: 1px solid var(--adv-cellar-line2);
  & span { display: flex; align-items: center; gap: 7px; height: 38px; padding: 0 14px; font-size: 11.5px; font-weight: 700; color: var(--adv-cellar-mute); }
  & span i { width: 8px; height: 8px; border-radius: 50%; background: var(--c); box-shadow: 0 0 0 3px color-mix(in oklch, var(--c) 22%, transparent); }
  & small { margin-left: auto; font: 500 10.5px var(--adv-cellar-mono); color: var(--adv-cellar-faint); }
}
@supports (animation-timeline: scroll()) {
  .adv-cellar .adv-cellar-head { animation: adv-cellar-lift linear both; animation-timeline: scroll(nearest block); animation-range: 0 30px; }
}
@keyframes adv-cellar-lift { to { box-shadow: 0 10px 18px -12px oklch(0 0 0 / .8); } }
.adv-cellar .adv-cellar-group { grid-column: 1 / -1; display: flex; align-items: center; gap: 8px; padding: 14px 14px 6px; font-size: 10.5px; font-weight: 750; letter-spacing: .1em; text-transform: uppercase; color: var(--adv-cellar-faint); & output { font-weight: 500; letter-spacing: 0; } }
.adv-cellar .adv-cellar-key {
  display: grid; align-content: center; gap: 2px; min-width: 0; padding: 8px 14px; cursor: pointer; text-align: left;
  & b { display: flex; align-items: center; gap: 6px; font: 600 12.5px var(--adv-cellar-mono); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & b svg { width: 13px; height: 13px; color: var(--adv-cellar-accent); }
  & small { font-size: 11px; color: var(--adv-cellar-faint); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & .warn { color: var(--adv-cellar-prd); }
}
.adv-cellar .adv-cellar-cell {
  position: relative; display: flex; align-items: center; gap: 6px; min-width: 0; padding: 0 8px 0 14px; border-left: 1px solid var(--adv-cellar-line); cursor: text; outline: none;
  & .v { flex: 1; min-width: 0; font: 12px var(--adv-cellar-mono); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; color: var(--adv-cellar-ink); }
  & .v .ref { color: var(--adv-cellar-accent); }
  & .mask { flex: 1; min-width: 0; display: flex; align-items: center; gap: 6px; font: 12px var(--adv-cellar-mono); color: var(--adv-cellar-faint); letter-spacing: .08em; white-space: nowrap; overflow: hidden; }
  & .mask b { font-weight: 500; letter-spacing: 0; color: var(--adv-cellar-mute); }
  & .reveal { clip-path: inset(0 0 0 0); transition: clip-path .5s var(--adv-cellar-ease); @starting-style { clip-path: inset(0 100% 0 0); } }
  & .eye { position: relative; display: grid; place-items: center; width: 26px; height: 26px; border-radius: 7px; color: var(--adv-cellar-faint); flex: none; }
  & .eye:hover { color: var(--adv-cellar-ink); background: var(--adv-cellar-hover); }
  & .eye svg { width: 15px; height: 15px; }
  & .eye.is-on { color: var(--adv-cellar-accent); }
  & .eye.is-on::before { content: ""; position: absolute; inset: 1px; border-radius: 50%; background: conic-gradient(var(--adv-cellar-accent) var(--adv-cellar-left), transparent 0); -webkit-mask: radial-gradient(farthest-side, transparent calc(100% - 2px), #000 calc(100% - 1.5px)); mask: radial-gradient(farthest-side, transparent calc(100% - 2px), #000 calc(100% - 1.5px)); animation: adv-cellar-count 10s linear forwards; }
  & .miss { display: inline-flex; align-items: center; gap: 6px; height: 26px; padding: 0 9px; border-radius: 7px; font-size: 11.5px; font-weight: 600; color: var(--adv-cellar-faint); box-shadow: inset 0 0 0 1px var(--adv-cellar-line2); background: repeating-linear-gradient(135deg, transparent 0 5px, var(--adv-cellar-hover) 5px 6px); }
  & .miss:hover { color: var(--adv-cellar-ink); box-shadow: inset 0 0 0 1px var(--adv-cellar-faint); }
  & .miss svg { width: 13px; height: 13px; }
  & .dot { position: absolute; left: 5px; top: 50%; width: 5px; height: 5px; margin-top: -2.5px; border-radius: 50%; background: var(--adv-cellar-accent); animation: adv-cellar-pulse 1.8s var(--adv-cellar-ease) infinite; }
  &:focus-visible, &.is-cursor { box-shadow: inset 0 0 0 2px var(--adv-cellar-accent); }
  & input { flex: 1; min-width: 0; height: 30px; padding: 0 8px; border: 0; border-radius: 6px; background: var(--adv-cellar-sunk); box-shadow: inset 0 0 0 1.5px var(--adv-cellar-accent); font: 12px var(--adv-cellar-mono); outline: none; }
}
@keyframes adv-cellar-count { to { --adv-cellar-left: 0deg; } }
@keyframes adv-cellar-pulse { 50% { opacity: .35; scale: .7; } }
.adv-cellar .adv-cellar-none { grid-column: 1 / -1; padding: 30px 16px; text-align: center; color: var(--adv-cellar-faint); font-size: 12.5px; }

/* pending bar */
.adv-cellar .adv-cellar-pending {
  display: flex; align-items: center; gap: 10px; padding: 10px 16px; border-top: 1px solid var(--adv-cellar-line); background: var(--adv-cellar-panel); font-size: 12.5px; min-width: 0;
  &:empty { display: none; }
  & .d { width: 8px; height: 8px; border-radius: 50%; background: var(--adv-cellar-accent); box-shadow: 0 0 0 3px var(--adv-cellar-tint); flex: none; }
  & .t { min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
  & .t b { font-weight: 700; }
  & .sp { flex: 1; }
  & .prog { flex: 1; display: grid; gap: 4px; font: 11.5px var(--adv-cellar-mono); color: var(--adv-cellar-mute); }
  & .prog i { display: block; height: 4px; border-radius: 2px; background: var(--adv-cellar-line); overflow: hidden; }
  & .prog i::before { content: ""; display: block; height: 100%; background: var(--adv-cellar-accent); transform-origin: left; animation: adv-cellar-deploy 2.2s cubic-bezier(.3, .1, .2, 1) forwards; }
  transition: opacity .3s, translate .45s var(--adv-cellar-spring); @starting-style { opacity: 0; translate: 0 10px; }
}
@keyframes adv-cellar-deploy { from { transform: scaleX(0); } to { transform: scaleX(1); } }

/* inspector */
.adv-cellar .adv-cellar-insp { grid-area: insp; min-height: 0; overflow-y: auto; scrollbar-width: thin; padding: 16px 14px; display: grid; align-content: start; gap: 14px; border-left: 1px solid var(--adv-cellar-line); background: var(--adv-cellar-panel); }
.adv-cellar .adv-cellar-ihead {
  display: grid; gap: 4px;
  & h2 { font: 700 15px var(--adv-cellar-mono); letter-spacing: -.01em; word-break: break-all; }
  & p { font-size: 12.5px; color: var(--adv-cellar-mute); text-wrap: pretty; }
  & .tags { display: flex; flex-wrap: wrap; gap: 5px; }
  & .tag { padding: 1px 7px; border-radius: 5px; font-size: 10.5px; font-weight: 700; letter-spacing: .04em; text-transform: uppercase; color: var(--adv-cellar-mute); box-shadow: inset 0 0 0 1px var(--adv-cellar-line2); }
  & .tag.secret { color: var(--adv-cellar-accent); box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--adv-cellar-accent) 40%, transparent); }
}
.adv-cellar .adv-cellar-envs {
  display: grid; gap: 6px;
  & div { display: grid; gap: 3px; padding: 9px 10px; border-radius: 10px; background: var(--adv-cellar-sunk); box-shadow: inset 3px 0 0 var(--c); }
  & span { display: flex; justify-content: space-between; font-size: 11px; font-weight: 700; color: var(--adv-cellar-mute); }
  & span small { font-weight: 500; color: var(--adv-cellar-faint); }
  & code { font: 12px var(--adv-cellar-mono); word-break: break-all; color: var(--adv-cellar-ink); }
  & code.no { color: var(--adv-cellar-prd); }
  & .res { font: 11px var(--adv-cellar-mono); color: var(--adv-cellar-faint); word-break: break-all; }
