const SAMPLE = '# From the payments team, 30 Sep\nPAYMENTS_WEBHOOK_SECRET=cellar-demo-wh-77c1f0a9e2b4d6\nTRACE_SAMPLE_RATE=0.1\nFEATURE_CHECKOUT_V2=true\nSEARCH_INDEX_NAME=orchard-products\npayments_region=eu-west\nTRACE_SAMPLE_RATE=0.2\n\nLOG_LEVEL="warn"  # unchanged';
