    if (t.startsWith('#')) return { n: i + 1, k: 'skip', b: 'comment', s: t };
    const m = /^(?:export\s+)?([^=\s]+)\s*=\s*(.*)$/.exec(t);
    if (!m) return { n: i + 1, k: 'bad', b: 'no =', s: t };
